def _add_real_sdk_dependency_approval_package_arguments(parser: argparse.ArgumentParser) -> None:
    parser.add_argument("--provider", required=True, choices=["openai"])
    parser.add_argument("--prompt-id", default="lab_generation_v0")
    parser.add_argument("--output-kind", default="Lab")
    parser.add_argument("--input-ref", default="examples/input/demo-source.md")
    parser.add_argument("--timeout-seconds", type=int, default=30)
    parser.add_argument("--retry-count", type=int, default=1)
    parser.add_argument("--concurrency-limit", type=int, default=1)
    parser.add_argument("--approval-ref")
    parser.add_argument("--reviewer")
    parser.add_argument("--confirm-dry-run-plan", action="store_true")
    parser.add_argument("--confirm-runtime-guard", action="store_true")
    parser.add_argument("--confirm-schema-review", action="store_true")
    parser.add_argument("--confirm-human-review-policy", action="store_true")
    parser.add_argument("--confirm-audit-redaction", action="store_true")
    parser.add_argument("--target-model-alias", default="provider-default-lab-json-model")
    parser.add_argument("--task-ref")
    parser.add_argument("--confirm-sdk-dependency-review", action="store_true")
    parser.add_argument("--confirm-provider-contract-review", action="store_true")
    parser.add_argument("--confirm-runtime-contract-review", action="store_true")
    parser.add_argument("--confirm-secret-injection-review", action="store_true")
    parser.add_argument("--confirm-network-access-review", action="store_true")
    parser.add_argument("--confirm-rollback-plan", action="store_true")
    parser.add_argument("--confirm-minimal-impl-review", action="store_true")
    parser.add_argument("--confirm-sdk-package-review", action="store_true")
    parser.add_argument("--confirm-sdk-version-pin-review", action="store_true")
