def _add_missing_real_sdk_dependency_confirmation_arguments(
    parser: argparse.ArgumentParser,
    request_class: type,
) -> None:
    existing = {option for action in parser._actions for option in action.option_strings}
    for field_name in request_class.__dataclass_fields__:
        if field_name.endswith("_reconfirmed"):
            flag_stem = field_name[: -len("_reconfirmed")]
            flags = [
                "--confirm-" + flag_stem.replace("_", "-"),
                "--confirm-" + field_name.replace("_", "-"),
            ]
        elif field_name.endswith("_confirmed"):
            flag_stem = field_name[: -len("_confirmed")]
            flags = ["--confirm-" + flag_stem.replace("_", "-")]
        elif field_name.endswith("_reviewed"):
            flag_stem = field_name[: -len("_reviewed")]
            flags = ["--confirm-" + flag_stem.replace("_", "-")]
        else:
            continue
        new_flags = [flag for flag in flags if flag not in existing]
        if new_flags:
            parser.add_argument(
                *new_flags,
                dest="confirm_" + flag_stem,
                action="store_true",
            )
            existing.update(new_flags)


class CliError(Exception):
    def __init__(
        self,
        code: str,
        message: str,
        errors: list[dict[str, str]] | None = None,
        extra: dict[str, Any] | None = None,
    ) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.errors = errors or []
        self.extra = extra or {}


def make_trace_id() -> str:
    return f"trace_{uuid4().hex[:12]}"


def ok(message: str, data: dict[str, Any], trace_id: str) -> dict[str, Any]:
    return {"success": True, "code": "OK", "message": message, "data": data, "traceId": trace_id}


def fail(
    code: str,
    message: str,
    trace_id: str,
    errors: list[dict[str, str]] | None = None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = {"success": False, "code": code, "message": message, "errors": errors or [], "traceId": trace_id}
    if extra:
        payload.update(extra)
    return payload


class JsonArgumentParser(argparse.ArgumentParser):
    def __init__(self, *args, **kwargs):
        kwargs.setdefault("allow_abbrev", False)
        super().__init__(*args, **kwargs)

    def error(self, message: str) -> None:
        raise SystemExit(2)

    def exit(self, status: int = 0, message: str | None = None) -> None:
        raise SystemExit(status)


