def _path(value: str) -> Path:
    return resolve_cli_path(value, root=ROOT, workspace=workspace_root(root=ROOT))


def _ensure_file(path: Path, field: str) -> None:
    if not path.exists() or not path.is_file():
        raise CliError("VALIDATION_ERROR", "参数错误", [{"field": field, "reason": "文件不存在"}])


def _validate_yaml(kind: str, path: Path) -> dict[str, Any]:
    try:
        document = load_yaml(path)
        validate_dsl(document, load_schema(kind, ROOT))
        return document
    except DslValidationError as exc:
        raise CliError("SCHEMA_VALIDATION_ERROR", "DSL Schema 校验失败", exc.errors) from exc


def _load_grading_for_controlled_plan(path: Path) -> dict[str, Any]:
    try:
        document = load_yaml(path)
    except DslValidationError as exc:
        raise CliError("SCHEMA_VALIDATION_ERROR", "DSL 读取失败", exc.errors) from exc
    if not isinstance(document, dict):
        raise CliError("SCHEMA_VALIDATION_ERROR", "Grading DSL 格式错误", [{"field": "$", "reason": "root must be object"}])
    if document.get("kind") != "Grading":
        raise CliError("SCHEMA_VALIDATION_ERROR", "Grading DSL 格式错误", [{"field": "$.kind", "reason": "expected Grading"}])
    if not isinstance(document.get("metadata"), dict):
        raise CliError("SCHEMA_VALIDATION_ERROR", "Grading DSL 格式错误", [{"field": "$.metadata", "reason": "expected object"}])
    spec = document.get("spec")
    if not isinstance(spec, dict):
        raise CliError("SCHEMA_VALIDATION_ERROR", "Grading DSL 格式错误", [{"field": "$.spec", "reason": "expected object"}])
    if not isinstance(spec.get("checks"), list):
        raise CliError("SCHEMA_VALIDATION_ERROR", "Grading DSL 格式错误", [{"field": "$.spec.checks", "reason": "expected array"}])
    return document


def _write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as file:
        json.dump(payload, file, ensure_ascii=False, indent=2)


def _review_center_agent_report_url(task_id: str, report_path: str) -> str:
    return "review-center.html?" + urlencode({"taskId": task_id, "agentReport": report_path})


def _query_url(path: str, **params: str | None) -> str:
    query = {key: value for key, value in params.items() if value}
    return path + ("?" + urlencode(query) if query else "")


def _build_real_llm_demo_entry_routes(
    *,
    verification_output_path: Path,
    bundle_output_path: Path,
    acceptance_output_path: Path,
    checklist_output_path: Path,
    close_loop_output_path: Path | None,
    close_loop: dict[str, Any] | None,
) -> dict[str, Any]:
    tasks = close_loop.get("createdTasks", {}) if isinstance(close_loop, dict) else {}
    task_ids = {
        kind: item.get("id")
        for kind, item in tasks.items()
        if isinstance(item, dict) and item.get("id")
    }
    lab_task_id = task_ids.get("lab")
    exam_task_id = task_ids.get("exam")
    grading_task_id = task_ids.get("grading")
    ppt_task_id = task_ids.get("ppt")
    agent_entity_ids = (
        close_loop.get("mockImports", {}).get("entityIds", {})
        if isinstance(close_loop, dict) and isinstance(close_loop.get("mockImports"), dict)
        else {}
    )
    controlled_report_path = None
    if isinstance(close_loop, dict):
        controlled_evidence = close_loop.get("controlledGradingEvidence", {})
        if isinstance(controlled_evidence, dict):
            controlled_report_path = controlled_evidence.get("reportPath")
    grading_report_path = controlled_report_path
    routes = {
        "component": "RealLlmDemoEntryRoutes",
        "mode": "LOCAL_REVIEW_NAVIGATION_ONLY",
        "reviewCenter": _query_url("review-center.html", taskId=lab_task_id),
        "reviewCenterAfterAgentEntityReturn": _query_url(
            "review-center.html",
            taskId=lab_task_id,
            agentEntityRefresh="1" if lab_task_id else None,
        ),
        "labReview": _query_url("lab-review.html", taskId=lab_task_id),
        "examReview": _query_url("exam-review.html", taskId=exam_task_id),
        "gradingReview": _query_url("grading-review.html", taskId=grading_task_id),
        "pptReview": _query_url("ppt-review.html", taskId=ppt_task_id),
        "agentEntities": _query_url(
            "agent-entities.html",
            entityId=agent_entity_ids.get("lab") if isinstance(agent_entity_ids, dict) else None,
            sourceTaskId=lab_task_id,
            entityKind="lab" if lab_task_id else None,
        ),
        "gradingReport": _query_url(
            "grading-report.html",
            file=str(grading_report_path) if grading_report_path else None,
            taskId=grading_task_id,
        ),
        "outputFiles": {
            "verification": str(verification_output_path),
            "bundle": str(bundle_output_path),
            "acceptanceSummary": str(acceptance_output_path),
            "checklist": str(checklist_output_path),
            "closeLoop": str(close_loop_output_path) if close_loop_output_path is not None else None,
            "controlledGradingReport": str(grading_report_path) if grading_report_path else None,
        },
        "taskIds": task_ids,
        "agentEntityIds": agent_entity_ids,
        "summary": {
            "reviewCenterRouteAvailable": bool(lab_task_id),
            "agentEntitiesRouteAvailable": bool(lab_task_id),
            "gradingReportRouteAvailable": bool(grading_report_path and grading_task_id),
            "closeLoopExecuted": close_loop is not None,
            "manualReviewRequired": True,
        },
        "safety": {
            "readOnlyNavigation": True,
            "newLlmRequestSent": False,
            "secretsRead": False,
            "networkAccess": False,
            "autoApproveAllowed": False,
            "autoPublishAllowed": False,
            "realAgentImport": False,
            "realPublish": False,
        },
    }
    return routes


def _write_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def _create_presentation_workspace(slug: str) -> Path:
    thread_id = os.environ.get("CODEX_THREAD_ID") or f"manual-{uuid4().hex[:8]}"
    workspace = ROOT / "outputs" / thread_id / "presentations" / slug / uuid4().hex[:12]
    workspace.mkdir(parents=True, exist_ok=True)
    return workspace


def _run_pptx_artifact_builder(
    dsl_path: Path,
    output_path: Path,
    manifest_path: Path | None,
    preview_path: Path | None,
    preview_dir: Path | None,
    contact_sheet_path: Path | None,
) -> dict[str, Any]:
    node_override = os.environ.get("CODEX_NODE_EXE")
    node_exe = shutil.which(node_override or "node")
    if node_exe is None and node_override:
        override_path = Path(node_override).expanduser()
        if override_path.is_file():
            node_exe = str(override_path)
    script_path = ROOT / "scripts" / "build_pptx_from_ppt_dsl.mjs"
    if node_exe is None:
        raise CliError(
            "DEPENDENCY_ERROR",
            "PPTX 构建依赖缺失",
            [{"field": "node", "reason": "未找到 Node.js，请安装 Node.js 或设置 CODEX_NODE_EXE"}],
        )
    _ensure_file(script_path, "script")
    workspace_dir = _create_presentation_workspace("pptx-artifact-build")
    try:
        args = [
            node_exe,
            str(script_path),
            "--dsl",
            str(dsl_path),
            "--out",
            str(output_path),
            "--workspace",
            str(workspace_dir),
        ]
        if manifest_path is not None:
            args.extend(["--manifest", str(manifest_path)])
        if preview_path is not None:
            args.extend(["--preview", str(preview_path)])
        if preview_dir is not None:
            args.extend(["--preview-dir", str(preview_dir)])
        if contact_sheet_path is not None:
            args.extend(["--contact-sheet", str(contact_sheet_path)])
        result = subprocess.run(
            args,
            cwd=str(ROOT),
            capture_output=True,
            text=True,
            encoding="utf-8",
            timeout=60,
            env={
                **os.environ,
                "HOME": os.environ.get("HOME") or str(Path.home()),
                "PYTHONIOENCODING": "utf-8",
                "LC_ALL": os.environ.get("LC_ALL", "C.UTF-8"),
                "LANG": os.environ.get("LANG", "C.UTF-8"),
            },
            check=False,
        )
    finally:
        shutil.rmtree(workspace_dir, ignore_errors=True)
    if result.returncode != 0:
        raise CliError(
            "PPTX_ARTIFACT_BUILD_ERROR",
            "PPTX Artifact 生成失败",
            [
                {
                    "field": "builder",
                    "reason": (result.stderr or result.stdout or "artifact-tool export failed").strip()[:1000],
                }
            ],
        )
    try:
        payload = _parse_builder_json_stdout(result.stdout)
    except json.JSONDecodeError as exc:
        raise CliError(
            "PPTX_ARTIFACT_BUILD_ERROR",
            "PPTX Artifact 生成失败",
            [{"field": "builder", "reason": f"构建脚本未返回 JSON: {exc}"}],
        ) from exc
    _ensure_file(output_path, "output")
    if output_path.stat().st_size <= 0:
        raise CliError("PPTX_ARTIFACT_BUILD_ERROR", "PPTX Artifact 生成失败", [{"field": "output", "reason": "输出文件为空"}])
    return payload


def _parse_builder_json_stdout(stdout: str) -> dict[str, Any]:
    stdout = stdout.strip()
    if not stdout:
        raise json.JSONDecodeError("empty builder stdout", stdout, 0)
    try:
        payload = json.loads(stdout)
    except json.JSONDecodeError:
        lines = stdout.splitlines()
        start_index = next((index for index, line in enumerate(lines) if line.lstrip().startswith("{")), None)
        if start_index is None:
            raise
        payload = json.loads("\n".join(lines[start_index:]))
    if not isinstance(payload, dict):
        raise json.JSONDecodeError("builder stdout root must be object", stdout, 0)
    return payload


def _read_json(path: Path) -> dict[str, Any]:
    try:
        with path.open("r", encoding="utf-8") as file:
            payload = json.load(file)
    except json.JSONDecodeError as exc:
        raise CliError("VALIDATION_ERROR", "JSON 文件格式错误", [{"field": "file", "reason": str(exc)}]) from exc
    if not isinstance(payload, dict):
        raise CliError("VALIDATION_ERROR", "JSON 文件格式错误", [{"field": "file", "reason": "root must be object"}])
    return payload


def _parse_json_object(value: str, field: str) -> dict[str, Any]:
    try:
        payload = json.loads(value)
    except json.JSONDecodeError as exc:
        raise CliError("VALIDATION_ERROR", "JSON 参数格式错误", [{"field": field, "reason": str(exc)}]) from exc
    if not isinstance(payload, dict):
        raise CliError("VALIDATION_ERROR", "JSON 参数格式错误", [{"field": field, "reason": "root must be object"}])
    return payload


def _real_sdk_dependency_dataclass_request_kwargs(
    args: argparse.Namespace,
    payload: dict[str, Any],
    trace_id: str,
    request_class: type,
) -> dict[str, Any]:
    values: dict[str, Any] = {
        "provider_id": args.provider,
        "operation": "generateJson",
        "prompt_id": args.prompt_id,
        "output_kind": args.output_kind,
        "input_ref": args.input_ref,
        "timeout_seconds": args.timeout_seconds,
        "retry_count": args.retry_count,
        "concurrency_limit": args.concurrency_limit,
        "payload": payload,
        "approval_ref": args.approval_ref,
        "reviewer": args.reviewer,
        "target_model_alias": args.target_model_alias,
        "task_ref": args.task_ref,
        "trace_id": trace_id,
    }
    for field_name in request_class.__dataclass_fields__:
        if field_name in values:
            continue
        if field_name.endswith("_confirmed"):
            attr_name = "confirm_" + field_name[: -len("_confirmed")]
        elif field_name.endswith("_reviewed"):
            attr_name = "confirm_" + field_name[: -len("_reviewed")]
        elif field_name.endswith("_reconfirmed"):
            attr_name = "confirm_" + field_name[: -len("_reconfirmed")]
        else:
            continue
        values[field_name] = bool(getattr(args, attr_name, False))
    return values


