def _raise_provider_error(
    exc: ProviderError,
    *,
    operation: str | None = None,
    provider_id: str | None = None,
    extra: dict[str, Any] | None = None,
) -> None:
    cli_extra = _provider_error_cli_extra(exc, operation=operation, provider_id=provider_id)
    if extra:
        cli_extra.update(extra)
    raise CliError(
        exc.code,
        exc.message,
        exc.errors,
        cli_extra,
    ) from exc


def _provider_error_cli_extra(
    exc: ProviderError,
    *,
    operation: str | None = None,
    provider_id: str | None = None,
) -> dict[str, Any]:
    details = exc.details if isinstance(getattr(exc, "details", None), dict) else {}
    if provider_id == "openai" and exc.code.startswith("REAL_LLM_"):
        context = {
            "adapterId": "openai_responses_sdk_adapter",
            "interfaceName": "LLMProvider",
            "operation": operation,
            "providerId": provider_id,
            "mode": "REAL_LLM",
            "errorCode": exc.code,
            "generatedContentCreated": False,
            "taskCreated": False,
            "reviewBypassed": False,
            "realLlmCalled": exc.code not in {
                "REAL_LLM_DEMO_DSL_CONFIRMATION_REQUIRED",
                "REAL_LLM_DEMO_DSL_SECRET_REQUIRED",
                "REAL_LLM_DEMO_DSL_MODEL_REQUIRED",
                "REAL_LLM_DEMO_DSL_SDK_IMPORT_FAILED",
                "REAL_LLM_DEMO_DSL_CLIENT_CREATE_FAILED",
                "REAL_LLM_MINIMAL_CALL_CONFIRMATION_REQUIRED",
                "REAL_LLM_MINIMAL_CALL_SECRET_REQUIRED",
                "REAL_LLM_MINIMAL_CALL_MODEL_REQUIRED",
                "REAL_LLM_MINIMAL_CALL_SDK_IMPORT_FAILED",
                "REAL_LLM_MINIMAL_CALL_CLIENT_CREATE_FAILED",
            },
            "secretsRead": True,
            "networkAccess": True,
            "autoPublishAllowed": False,
            "realPublish": False,
        }
    else:
        context = build_provider_error_context(exc, operation=operation, provider_id=provider_id)
    schema_failure_diagnostic = details.get("schemaFailureDiagnostic")
    if isinstance(schema_failure_diagnostic, dict):
        context["schemaFailureDiagnostic"] = schema_failure_diagnostic
    extra = {"providerErrorContext": context}
    if details:
        extra["details"] = details
    return extra


def _build_phase2_workflow_failure_report(
    *,
    input_path: Path,
    output_path: Path,
    provider_mode: str,
    exc: ProviderError,
    provider_error_context: dict[str, Any],
    material_analysis: dict[str, Any],
    real_output_refs: dict[str, str | None],
    real_demo_output_refs: dict[str, str | None],
    trace_id: str,
) -> dict[str, Any]:
    schema_failure_diagnostic = provider_error_context.get("schemaFailureDiagnostic")
    return {
        "workflowId": PHASE2_WORKFLOW_ID,
        "phase": "Phase 2",
        "mode": "PHASE2_WORKFLOW_FAILURE_REPORT",
        "status": "FAILED",
        "providerMode": provider_mode,
        "inputRef": str(input_path),
        "reportPath": str(output_path),
        "code": exc.code,
        "message": exc.message,
        "errors": exc.errors,
        "providerErrorContext": provider_error_context,
        "schemaFailureDiagnostic": schema_failure_diagnostic if isinstance(schema_failure_diagnostic, dict) else None,
        "materialAnalysisSummary": _material_analysis_failure_summary(material_analysis),
        "partialOutputs": {
            "realLlmOutputs": _output_ref_existence_summary(real_output_refs),
            "realDemoOutputs": _output_ref_existence_summary(real_demo_output_refs),
        },
        "generatedContentCreated": False,
        "taskCreated": False,
        "reviewRequired": True,
        "reviewBypassed": False,
        "autoPublishAllowed": False,
        "realPublish": False,
        "nextRecommendedAction": (
            "inspect_schema_failure_diagnostic_and_regenerate_or_enable_repair"
            if exc.code == "REAL_LLM_DEMO_DSL_SCHEMA_VALIDATION_FAILED"
            else "inspect_provider_error_and_retry_after_fixing_configuration_or_network"
        ),
        "safety": {
            "realLlmCalled": bool(provider_error_context.get("realLlmCalled")),
            "secretsRead": bool(provider_error_context.get("secretsRead")),
            "networkAccess": bool(provider_error_context.get("networkAccess")),
            "realCloudResourceChanged": False,
            "sandboxExecuted": False,
            "contestantCodeExecuted": False,
            "reviewBypassed": False,
            "autoPublishAllowed": False,
            "realPublish": False,
            "secretValueReturned": False,
            "secretValueLogged": False,
        },
        "redaction": {
            "secretValuesIncluded": False,
            "rawGeneratedDslIncluded": False,
            "standardAnswersIncluded": False,
        },
        "traceId": trace_id,
    }


def _material_analysis_failure_summary(material_analysis: dict[str, Any]) -> dict[str, Any]:
    return {
        "sourceType": material_analysis.get("sourceType"),
        "inputRef": material_analysis.get("inputRef"),
        "summary": material_analysis.get("summary"),
        "signals": material_analysis.get("signals", {}),
    }


def _output_ref_existence_summary(refs: dict[str, str | None]) -> dict[str, dict[str, Any]]:
    summary: dict[str, dict[str, Any]] = {}
    for kind, ref in refs.items():
        path = _path(ref) if ref else None
        summary[kind] = {
            "path": str(path) if path is not None else None,
            "exists": bool(path and path.exists()),
        }
    return summary


def _raise_material_error(exc: MaterialAnalysisError) -> None:
    raise CliError(exc.code, exc.message, exc.errors) from exc


def _get_nested_value(payload: dict[str, Any], path: str) -> Any:
    current: Any = payload
    for part in path.split("."):
        if isinstance(current, dict) and part in current:
            current = current[part]
        else:
            return None
    return current


def _build_delivery_manifest(contract: dict[str, Any]) -> dict[str, Any]:
    items = []
    for deliverable in contract["deliverables"]:
        path = ROOT / deliverable["path"]
        exists = path.exists()
        required = bool(deliverable.get("required", False))
        status = "READY" if exists else ("MISSING" if required else "OPTIONAL_MISSING")
        items.append({**deliverable, "exists": exists, "status": status})

    required_items = [item for item in items if item["required"]]
    missing_required = [item["id"] for item in required_items if not item["exists"]]
    return {
        "items": items,
        "summary": {
            "total": len(items),
            "required": len(required_items),
            "ready": sum(1 for item in items if item["status"] == "READY"),
            "missingRequired": len(missing_required),
            "missingRequiredIds": missing_required,
        },
    }


def _evaluate_acceptance_item(
    item: dict[str, Any],
    check_result: dict[str, Any],
    workflow_report: dict[str, Any],
    delivery_manifest: dict[str, Any],
) -> dict[str, Any]:
    source = item["source"]
    source_type = source["type"]
    passed = False
    evidence: dict[str, Any] = {"sourceType": source_type}

    if source_type == "phase1Check":
        check_map = {check["name"]: check["passed"] for check in check_result["checks"]}
        results = {name: check_map.get(name, False) for name in source["checks"]}
        passed = all(results.values())
        evidence["checks"] = results
    elif source_type == "workflowReport":
        actual = _get_nested_value(workflow_report, source["path"])
        passed = actual == source["expected"]
        evidence.update({"path": source["path"], "expected": source["expected"], "actual": actual})
    elif source_type == "deliverables":
        deliverables = {deliverable["id"]: deliverable for deliverable in delivery_manifest["items"]}
        results = {
            deliverable_id: deliverables.get(deliverable_id, {}).get("exists", False)
            for deliverable_id in source["ids"]
        }
        passed = all(results.values())
        evidence["deliverables"] = results

    return {
        "id": item["id"],
        "title": item["title"],
        "category": item["category"],
        "required": bool(item.get("required", False)),
        "passed": passed,
        "evidence": evidence,
    }


def _build_safety_assertions(contract: dict[str, Any]) -> list[dict[str, Any]]:
    return [
        {
            **assertion,
            "passed": assertion.get("actual") == assertion.get("expected"),
        }
        for assertion in contract["safetyAssertions"]
    ]


def _build_acceptance_summary(
    acceptance_checklist: list[dict[str, Any]],
    delivery_manifest: dict[str, Any],
    safety_assertions: list[dict[str, Any]],
) -> dict[str, Any]:
    required_items = [item for item in acceptance_checklist if item["required"]]
    required_passed = sum(1 for item in required_items if item["passed"])
    safety_passed = all(assertion["passed"] for assertion in safety_assertions)
    missing_required = delivery_manifest["summary"]["missingRequired"]
    passed = required_passed == len(required_items) and missing_required == 0 and safety_passed
    return {
        "passed": passed,
        "readyForPhase2MockHandoff": passed,
        "total": len(acceptance_checklist),
        "passedCount": sum(1 for item in acceptance_checklist if item["passed"]),
        "requiredTotal": len(required_items),
        "requiredPassed": required_passed,
        "missingRequiredDeliverables": missing_required,
        "safetyAssertionsPassed": safety_passed,
    }


def _check_item(name: str, passed: bool, detail: dict[str, Any] | None = None) -> dict[str, Any]:
    return {"name": name, "passed": passed, "detail": detail or {}}


def _provider_error_to_cli(exc: ProviderError) -> CliError:
    return CliError(
        exc.code,
        exc.message,
        exc.errors,
        {"providerErrorContext": build_provider_error_context(exc, operation="generateJson", provider_id="mock")},
    )


def _run_phase1_check(input_arg: str) -> dict[str, Any]:
    from backend.mock_api import handle_request

    checks: list[dict[str, Any]] = []
    input_path = _path(input_arg)
    _ensure_file(input_path, "input")

    for kind, relative_path in {
        "lab": "templates/lab/examples/basic-lab.yaml",
        "exam": "templates/exam/examples/notebook-fill-blank.yaml",
        "grading": "templates/grading/examples/python-pytest.yaml",
        "ppt": "templates/ppt/examples/course-ppt.yaml",
    }.items():
        path = ROOT / relative_path
        document = _validate_yaml(kind, path)
        checks.append(
            _check_item(
                f"dsl_{kind}",
                True,
                {"path": relative_path, "dslId": document.get("metadata", {}).get("id"), "status": document.get("status")},
            )
        )

    with tempfile.TemporaryDirectory() as temp_dir:
        temp_path = Path(temp_dir)
        store_path = temp_path / "store.json"
        report_path = temp_path / "workflow-report.json"
        store = JsonTaskStore(store_path)

        lab_task = create_waiting_review_task(
            task_type="LAB_GENERATION",
            title="Phase1 check lab",
            input_type="markdown",
            input_ref=str(input_path),
            final_result_path="templates/lab/examples/basic-lab.yaml",
        )
        store.save(lab_task)
        checks.append(_check_item("ai_task_waiting_review", lab_task.status.value == "WAITING_REVIEW", {"taskId": lab_task.id}))

        try:
            lab_task.transition_to(TaskStatus.COMPLETED)
            publish_blocked = False
        except ValueError:
            publish_blocked = True
        checks.append(_check_item("unreviewed_publish_blocked", publish_blocked))

        environment = EnvironmentInstance(envType=EnvironmentType.VM, title="Phase1 check VM", image="ubuntu-22.04")
        store.save_environment(environment)
        checks.append(
            _check_item(
                "environment_mock_created",
                environment.status.value == "CREATED" and environment.provider == "mock",
                {"envId": environment.id},
            )
        )

        grading = _validate_yaml("grading", ROOT / "templates/grading/examples/python-pytest.yaml")
        report_payload = {
            "id": f"report_{uuid4().hex[:12]}",
            "mode": "MOCK_ONLY",
            "input": str(input_path),
            "steps": [
                {"name": "generate_lab_dsl", "status": "WAITING_REVIEW"},
                {"name": "generate_exam_dsl", "status": "WAITING_REVIEW"},
                {"name": "generate_grading_dsl", "status": "WAITING_REVIEW"},
                {"name": "mock_grade_run", "status": "COMPLETED", "report": {"earnedScore": grading["spec"]["totalScore"]}},
            ],
            "reviewRequired": True,
            "publishBlockedUntilApproved": True,
        }
        _write_json(report_path, report_payload)
        checks.append(_check_item("workflow_report_written", report_path.exists(), {"path": str(report_path)}))

        health = handle_request("GET", "/api/health", store_path=store_path)
        tasks = handle_request("GET", "/api/ai-tasks?status=WAITING_REVIEW", store_path=store_path)
        environments = handle_request("GET", "/api/environments?type=vm", store_path=store_path)
        report = handle_request("GET", f"/api/workflow/report?file={report_path}", store_path=store_path)
        try:
            provider_registry = build_provider_registry(ROOT)
            provider_health = get_provider_health("mock", ROOT)
            provider_output = invoke_provider("generateJson", prompt_id="lab_generation_v0", root=ROOT)
            provider_ok = (
                provider_registry["activeProvider"] == "mock"
                and provider_registry["realLlmCalled"] is False
                and provider_registry["secretsRead"] is False
                and provider_registry["networkAccess"] is False
            )
        except ProviderError:
            provider_registry = {}
            provider_health = {}
            provider_output = {}
            provider_ok = False
        checks.append(_check_item("backend_health", health.get("success") is True, {"mode": health.get("data", {}).get("mode")}))
        checks.append(_check_item("backend_ai_tasks", tasks.get("data", {}).get("total") == 1))
        checks.append(_check_item("backend_environments", environments.get("data", {}).get("total") == 1))
        checks.append(_check_item("backend_workflow_report", report.get("data", {}).get("report", {}).get("mode") == "MOCK_ONLY"))
        try:
            material_analysis = analyze_material(input_path, trace_id="trace_phase1_material")
            material_ok = (
                material_analysis["mode"] == "MOCK_ONLY"
                and material_analysis["realLlmCalled"] is False
                and material_analysis["unknownShellExecuted"] is False
            )
        except MaterialAnalysisError:
            material_analysis = {}
            material_ok = False
        checks.append(
            _check_item(
                "material_analysis_mock",
                material_ok,
                {"fileType": material_analysis.get("fileType"), "riskCount": material_analysis.get("riskCount")},
            )
        )
        artifact_record = _save_artifact(
            store,
            kind=ArtifactKind.LAB_DSL,
            path="templates/lab/examples/basic-lab.yaml",
            title="Phase1 check Lab DSL",
            status=ArtifactStatus.WAITING_REVIEW,
            trace_id="trace_phase1_check",
            task_id=lab_task.id,
            source_ref=str(input_path),
            metadata={"dslKind": "Lab", "reviewRequired": True},
        )
        artifacts = handle_request("GET", "/api/artifacts?kind=LAB_DSL", store_path=store_path)
        artifact_item = artifacts.get("data", {}).get("items", [{}])[0] if artifacts.get("data", {}).get("items") else {}
        checks.append(
            _check_item(
                "artifact_manifest_mock",
                artifacts.get("data", {}).get("total") == 1
                and artifact_item.get("id") == artifact_record["id"]
                and artifact_item.get("mode") == "MOCK_ONLY"
                and artifact_item.get("realLlmCalled") is False
                and artifact_item.get("realPublish") is False,
                {"artifactId": artifact_record["id"], "kind": artifact_record["kind"]},
            )
        )
        review_detail = handle_request("GET", f"/api/review-tasks/{lab_task.id}", store_path=store_path)
        detail_data = review_detail.get("data", {}).get("reviewDetail", {})
        checks.append(
            _check_item(
                "review_detail_mock",
                review_detail.get("success") is True
                and detail_data.get("task", {}).get("id") == lab_task.id
                and detail_data.get("summary", {}).get("artifactTotal") == 1
                and detail_data.get("reviewPolicy", {}).get("publishBlockedUntilApproved") is True
                and detail_data.get("reviewPolicy", {}).get("allowedActions")
                == ["approve", "reject", "request_revision"]
                and detail_data.get("reviewPage", {}).get("dslPreview", {}).get("artifactKind") == "LAB_DSL"
                and detail_data.get("reviewPage", {}).get("actionBar", {}).get("requestRevision", {}).get("enabled")
                is True
                and detail_data.get("reviewPage", {}).get("actionBar", {}).get("mockPublish", {}).get("enabled") is False
                and detail_data.get("safety", {}).get("realPublish") is False,
                {"taskId": lab_task.id},
            )
        )
        review_batch = handle_request("GET", "/api/review-task-summary?status=WAITING_REVIEW", store_path=store_path)
        batch_data = review_batch.get("data", {}).get("reviewTaskSummary", {})
        checks.append(
            _check_item(
                "review_batch_summary_mock",
                review_batch.get("success") is True
                and batch_data.get("total") == 1
                and batch_data.get("queueSummary", {}).get("waitingReviewTotal") == 1
                and batch_data.get("batchActionPolicy", {}).get("batchApproveAllowed") is False
                and batch_data.get("batchActionPolicy", {}).get("batchPublishAllowed") is False
                and batch_data.get("safety", {}).get("realPublish") is False,
                {"total": batch_data.get("total")},
            )
        )
        workflow_run = create_workflow_run(
            workflow_id="phase1_check",
            input_ref=str(input_path),
            reviewer="phase1_check",
            trace_id="trace_phase1_check",
            report_path=str(report_path),
            steps=[
                create_workflow_step("generate_lab_dsl", 1, {"status": "WAITING_REVIEW"}),
                create_workflow_step("mock_grade_run", 2, {"sandboxExecuted": False}),
            ],
        )
        store.save_workflow_run(workflow_run)
        stored_run = store.get_workflow_run(workflow_run.id)
        checks.append(
            _check_item(
                "workflow_run_logged",
                stored_run is not None
                and stored_run.status.value == "COMPLETED"
                and stored_run.realLlmCalled is False
                and stored_run.steps[0].name == "generate_lab_dsl",
                {"workflowRunId": workflow_run.id},
            )
        )
        checks.append(_check_item("provider_mock_only", provider_ok, {"activeProvider": provider_registry.get("activeProvider")}))
        checks.append(
            _check_item(
                "provider_health",
                provider_health.get("status") == "UP" and provider_health.get("realLlmCalled") is False,
                {"providerId": provider_health.get("providerId")},
            )
        )
        checks.append(
            _check_item(
                "provider_mock_generate",
                provider_output.get("generatedStatus") == "WAITING_REVIEW"
                and provider_output.get("realLlmCalled") is False
                and provider_output.get("dslPath") == "templates/lab/examples/basic-lab.yaml",
                {"promptId": provider_output.get("promptId"), "dslId": provider_output.get("dslId")},
            )
        )

    passed = all(item["passed"] for item in checks)
    return {"passed": passed, "checks": checks, "total": len(checks)}


def _build_workflow_report(input_path: Path, reviewer: str, trace_id: str) -> dict[str, Any]:
    try:
        bundle = generate_workflow_dsl_bundle(input_ref=str(input_path), trace_id=trace_id, root=ROOT)
    except ProviderError as exc:
        raise _provider_error_to_cli(exc) from exc
    lab = bundle["lab"]
    exam = bundle["exam"]
    grading = bundle["grading"]
    ppt = bundle["ppt"]
    grading_dsl = grading["dsl"]
    checks = grading_dsl["spec"]["checks"]
    return {
        "id": f"report_{uuid4().hex[:12]}",
        "mode": "MOCK_ONLY",
        "providerAdapter": "mock_provider_adapter",
        "input": str(input_path),
        "reviewer": reviewer,
        "steps": [
            {
                "name": "generate_lab_dsl",
                "status": "WAITING_REVIEW",
                "dslPath": lab["dslPath"],
                "dslId": lab["dslId"],
                "provider": lab["provider"],
            },
            {
                "name": "generate_exam_dsl",
                "status": "WAITING_REVIEW",
                "dslPath": exam["dslPath"],
                "dslId": exam["dslId"],
                "provider": exam["provider"],
            },
            {
                "name": "generate_grading_dsl",
                "status": "WAITING_REVIEW",
                "dslPath": grading["dslPath"],
                "dslId": grading["dslId"],
                "provider": grading["provider"],
            },
            {
                "name": "generate_ppt_dsl",
                "status": "WAITING_REVIEW",
                "dslPath": ppt["dslPath"],
                "dslId": ppt["dslId"],
                "provider": ppt["provider"],
            },
            {
                "name": "mock_grade_run",
                "status": "COMPLETED",
                "report": {
                    "totalScore": grading_dsl["spec"]["totalScore"],
                    "earnedScore": grading_dsl["spec"]["totalScore"],
                    "passed": True,
                    "checks": [
                        {"id": check["id"], "type": check["type"], "score": check["score"], "passed": True}
                        for check in checks
                    ],
                },
            },
        ],
        "reviewRequired": True,
        "publishBlockedUntilApproved": True,
        "traceId": trace_id,
    }


def _create_phase2_review_tasks(
    store: JsonTaskStore,
    *,
    report: dict[str, Any],
    input_ref: str,
    trace_id: str,
) -> dict[str, dict[str, Any]]:
    generated = report["generatedDsl"]
    task_specs = {
        "lab": (
            "LAB_GENERATION",
            "Phase 2 Mock Lab DSL generation",
            "markdown",
            input_ref,
            generated["lab"]["dslPath"],
        ),
        "exam": (
            "EXAM_GENERATION",
            "Phase 2 Mock Exam DSL generation",
            "lab_dsl",
            generated["lab"]["dslId"],
            generated["exam"]["dslPath"],
        ),
        "grading": (
            "GRADING_GENERATION",
            "Phase 2 Mock Grading DSL generation",
            "exam_dsl",
            generated["exam"]["dslId"],
            generated["grading"]["dslPath"],
        ),
        "ppt": (
            "PPT_GENERATION",
            "Phase 2 Mock PPT DSL generation",
            "markdown",
            input_ref,
            generated["ppt"]["dslPath"],
        ),
    }
    tasks: dict[str, dict[str, Any]] = {}
    for kind, (task_type, title, input_type, source_ref, final_result_path) in task_specs.items():
        generation = report.get("providerGenerations", {}).get(kind, {})
        provider = generation.get("provider", {})
        task = create_waiting_review_task(
            task_type=task_type,
            title=title,
            input_type=input_type,
            input_ref=source_ref,
            final_result_path=final_result_path,
            trace_id=trace_id,
        )
        if provider.get("realLlmCalled"):
            real_label = (
                "Real LLM Demo"
                if provider.get("adapterId") == "openai_responses_sdk_demo_adapter"
                else "Real LLM Minimal"
            )
            task.title = title.replace("Mock", real_label)
            task.modelName = str(provider.get("model") or provider.get("providerId") or "openai")
            task.promptVersion = str(generation.get("promptVersion") or generation.get("promptId") or "real-llm-minimal-poc-v2")
        store.save(task)
        tasks[kind] = task.to_dict()
    return tasks


def _attach_phase2_task_ids(report: dict[str, Any], tasks: dict[str, dict[str, Any]]) -> None:
    generated = report.get("generatedDsl", {})
    for kind, task in tasks.items():
        if isinstance(generated.get(kind), dict):
            generated[kind]["taskId"] = task["id"]
    steps = report.get("steps")
    if not isinstance(steps, list):
        return
    for step in steps:
        if not isinstance(step, dict):
            continue
        kind = step.get("kind")
        if kind in tasks:
            step["taskId"] = tasks[kind]["id"]


def _save_phase2_artifacts(
    store: JsonTaskStore,
    *,
    report: dict[str, Any],
    input_path: Path,
    output_path: Path,
    tasks: dict[str, dict[str, Any]],
    trace_id: str,
) -> list[dict[str, Any]]:
    generated = report["generatedDsl"]
    provider_generations = report.get("providerGenerations", {})
    providers = {
        kind: provider_generations.get(kind, {}).get("provider", generated.get(kind, {}).get("provider", {}))
        for kind in ("lab", "exam", "grading", "ppt")
    }
    safety = report.get("safety", {})
    lab_generation_context = report.get("labGenerationContext", {})
    quality_signals = report.get("qualitySignals", {})
    content_quality_summary = report.get("contentQualitySummary", {})
    content_quality_items = (
        content_quality_summary.get("items", {})
        if isinstance(content_quality_summary, dict) and isinstance(content_quality_summary.get("items"), dict)
        else {}
    )

    def provider_adapter(kind: str) -> str:
        return str(providers[kind].get("adapterId") or "mock_provider_adapter")

    def provider_mode(kind: str) -> str:
        return str(providers[kind].get("mode") or "MOCK_ONLY")

    def provider_real(kind: str) -> bool:
        return bool(providers[kind].get("realLlmCalled", False))

    def provider_summary(kind: str) -> dict[str, Any]:
        generation = provider_generations.get(kind, {})
        provider = providers[kind]
        quality_summary = generated.get(kind, {}).get("qualitySummary")
        if not isinstance(quality_summary, dict) and generation:
            quality_summary = _build_generation_quality_summary(kind, generation)
        return {
            "providerId": provider.get("providerId"),
            "adapterId": provider.get("adapterId"),
            "mode": provider.get("mode"),
            "model": provider.get("model"),
            "promptId": generation.get("promptId"),
            "outputKind": generation.get("outputKind") or generated.get(kind, {}).get("kind"),
            "responseId": generation.get("responseId") or provider.get("responseId"),
            "usage": generation.get("usage"),
            "apiSurface": generation.get("apiSurface") or provider.get("apiSurface"),
            "normalization": generation.get("normalization"),
            "qualitySummary": quality_summary,
            "realLlmCalled": bool(provider.get("realLlmCalled", False)),
            "networkAccess": bool(provider.get("networkAccess", False)),
            "requestCount": provider.get("requestCount"),
            "singleRequestOnly": provider.get("singleRequestOnly"),
        }

    def dsl_title(kind: str, label: str) -> str:
        if not provider_real(kind):
            prefix = "Phase 2 Mock"
        elif provider_adapter(kind) == "openai_responses_sdk_demo_adapter":
            prefix = "Phase 2 Real LLM Demo"
        else:
            prefix = "Phase 2 Real LLM Minimal"
        return f"{prefix} {label} DSL"

    report_steps = report.get("steps", [])
    if not isinstance(report_steps, list):
        report_steps = []
    material_step = next(
        (step for step in report_steps if isinstance(step, dict) and step.get("name") == "analyze_material"),
        {},
    )
    material_analysis = material_step.get("materialAnalysis", {})
    return [
        _save_artifact(
            store,
            kind=ArtifactKind.MATERIAL_ANALYSIS,
            path=str(input_path),
            title=str(material_analysis.get("title") or "Phase 2 Mock Source Material"),
            status=ArtifactStatus.COMPLETED,
            trace_id=trace_id,
            source_ref=str(input_path),
            metadata={
                "fileType": material_analysis.get("fileType"),
                "riskCount": material_analysis.get("riskCount", 0),
                "unknownShellExecuted": material_analysis.get("unknownShellExecuted", False),
                "workflowId": PHASE2_WORKFLOW_ID,
            },
        ),
        _save_artifact(
            store,
            kind=ArtifactKind.LAB_DSL,
            path=generated["lab"]["dslPath"],
            title=dsl_title("lab", "Lab"),
            status=ArtifactStatus.WAITING_REVIEW,
            trace_id=trace_id,
            task_id=tasks["lab"]["id"],
            source_ref=str(input_path),
            metadata={
                "dslKind": "Lab",
                "reviewRequired": True,
                "providerAdapter": provider_adapter("lab"),
                "workflowId": PHASE2_WORKFLOW_ID,
                "generationContext": lab_generation_context,
                "qualitySignals": quality_signals.get("lab", {}),
                "workflowQualitySignals": quality_signals,
                "qualitySignalSummary": quality_signals.get("overall", {}),
                "reviewHighlights": quality_signals.get("reviewHighlights", []),
                "contentQualitySummary": content_quality_items.get("lab", {}),
                "workflowContentQualitySummary": content_quality_summary,
                "providerSummary": provider_summary("lab"),
            },
            mode=provider_mode("lab"),
            real_llm_called=provider_real("lab"),
        ),
        _save_artifact(
            store,
            kind=ArtifactKind.EXAM_DSL,
            path=generated["exam"]["dslPath"],
            title=dsl_title("exam", "Exam"),
            status=ArtifactStatus.WAITING_REVIEW,
            trace_id=trace_id,
            task_id=tasks["exam"]["id"],
            source_ref=generated["lab"]["dslId"],
            metadata={
                "dslKind": "Exam",
                "answerVisibleToCandidate": False,
                "providerAdapter": provider_adapter("exam"),
                "workflowId": PHASE2_WORKFLOW_ID,
                "contentQualitySummary": content_quality_items.get("exam", {}),
                "workflowContentQualitySummary": content_quality_summary,
                "providerSummary": provider_summary("exam"),
            },
            mode=provider_mode("exam"),
            real_llm_called=provider_real("exam"),
        ),
        _save_artifact(
            store,
            kind=ArtifactKind.GRADING_DSL,
            path=generated["grading"]["dslPath"],
            title=dsl_title("grading", "Grading"),
            status=ArtifactStatus.WAITING_REVIEW,
            trace_id=trace_id,
            task_id=tasks["grading"]["id"],
            source_ref=generated["exam"]["dslId"],
            metadata={
                "dslKind": "Grading",
                "reviewRequired": True,
                "providerAdapter": provider_adapter("grading"),
                "workflowId": PHASE2_WORKFLOW_ID,
                "contentQualitySummary": content_quality_items.get("grading", {}),
                "workflowContentQualitySummary": content_quality_summary,
                "providerSummary": provider_summary("grading"),
            },
            mode=provider_mode("grading"),
            real_llm_called=provider_real("grading"),
        ),
        _save_artifact(
            store,
            kind=ArtifactKind.PPT_DSL,
            path=generated["ppt"]["dslPath"],
            title=dsl_title("ppt", "PPT"),
            status=ArtifactStatus.WAITING_REVIEW,
            trace_id=trace_id,
            task_id=tasks["ppt"]["id"],
            source_ref=str(input_path),
            metadata={
                "dslKind": "PPT",
                "artifactGenerated": False,
                "providerAdapter": provider_adapter("ppt"),
                "workflowId": PHASE2_WORKFLOW_ID,
                "contentQualitySummary": content_quality_items.get("ppt", {}),
                "workflowContentQualitySummary": content_quality_summary,
                "providerSummary": provider_summary("ppt"),
            },
            mode=provider_mode("ppt"),
            real_llm_called=provider_real("ppt"),
        ),
        _save_artifact(
            store,
            kind=ArtifactKind.WORKFLOW_REPORT,
            path=str(output_path),
            title=str(report.get("title") or "Phase 2 Content Generation Report"),
            status=ArtifactStatus.COMPLETED,
            trace_id=trace_id,
            source_ref=str(input_path),
            metadata={
                "workflowId": PHASE2_WORKFLOW_ID,
                "reviewRequired": True,
                "generationContext": lab_generation_context,
                "qualitySignalSummary": quality_signals.get("overall", {}),
                "reviewHighlights": quality_signals.get("reviewHighlights", []),
                "contentQualitySummary": content_quality_summary,
            },
            mode=str(report.get("mode") or "MOCK_ONLY"),
            real_llm_called=bool(safety.get("realLlmCalled", False)),
            real_cloud_resource_changed=bool(safety.get("realCloudResourceChanged", False)),
            sandbox_executed=bool(safety.get("sandboxExecuted", False)),
            contestant_code_executed=bool(safety.get("contestantCodeExecuted", False)),
            real_publish=bool(safety.get("realPublish", False)),
        ),
    ]


def _summarize_phase2_report(report: dict[str, Any]) -> dict[str, Any]:
    generated = report.get("generatedDsl", {})
    return {
        "workflowId": report.get("workflowId"),
        "phase": report.get("phase"),
        "mode": report.get("mode"),
        "providerAdapter": report.get("providerAdapter"),
        "labGenerationContext": report.get("labGenerationContext", {}),
        "qualitySignals": {
            "overall": report.get("qualitySignals", {}).get("overall", {}),
            "reviewHighlights": report.get("qualitySignals", {}).get("reviewHighlights", []),
        },
        "reviewRequired": report.get("reviewSummary", {}).get("reviewRequired"),
        "publishBlockedUntilApproved": report.get("reviewSummary", {}).get("publishBlockedUntilApproved"),
        "generatedDsl": {
            kind: {
                "dslId": value.get("dslId"),
                "dslPath": value.get("dslPath"),
                "status": value.get("status"),
                "reviewRequired": value.get("reviewRequired"),
            }
            for kind, value in generated.items()
        },
        "safety": report.get("safety", {}),
        "traceId": report.get("traceId"),
    }


def _build_offline_demo_summary(
    *,
    report: dict[str, Any],
    input_path: Path,
    workflow_output_path: Path,
    candidate_preview_output_path: Path,
    candidate_preview: dict[str, Any],
) -> dict[str, Any]:
    generated = report.get("generatedDsl", {})
    schema_checks = report.get("qualitySignals", {}).get("schemaChecks", {})
    content_quality = report.get("contentQualitySummary", {})
    quality_items = content_quality.get("items", {}) if isinstance(content_quality, dict) else {}
    dsl_summary = {
        kind: {
            "dslId": item.get("dslId"),
            "path": item.get("dslPath"),
            "schemaValidated": schema_checks.get(kind, {}).get("schemaValidated") is True,
            "status": item.get("status"),
            "reviewRequired": item.get("reviewRequired") is True,
            "qualityStatus": quality_items.get(kind, {}).get("status"),
            "blockingIssueTotal": quality_items.get(kind, {}).get("blockingIssueTotal", 0),
            "warningIssueTotal": quality_items.get(kind, {}).get("warningIssueTotal", 0),
        }
        for kind, item in generated.items()
        if isinstance(item, dict)
    }
    expected_kinds = {"lab", "exam", "grading", "ppt"}
    schema_validated = set(dsl_summary) == expected_kinds and all(
        item["schemaValidated"] for item in dsl_summary.values()
    )
    review_gated = set(dsl_summary) == expected_kinds and all(
        item["status"] == TaskStatus.WAITING_REVIEW.value and item["reviewRequired"]
        for item in dsl_summary.values()
    )
    review_summary = report.get("reviewSummary", {})
    review_required = review_summary.get("reviewRequired") is True
    publish_blocked = review_summary.get("publishBlockedUntilApproved") is True
    candidate_safe = (
        candidate_preview.get("answersRemoved") is True
        and candidate_preview.get("answerVisibleToCandidate") is False
        and candidate_preview.get("redaction", {}).get("answerLeakDetected") is False
    )
    summary = {
        "status": "PASS"
        if schema_validated and review_gated and candidate_safe and review_required and publish_blocked
        else "FAIL",
        "mode": "offline",
        "workflowId": report.get("workflowId"),
        "input": str(input_path),
        "workflowReportPath": str(workflow_output_path),
        "candidatePreviewPath": str(candidate_preview_output_path),
        "labValidated": dsl_summary.get("lab", {}).get("schemaValidated", False),
        "examValidated": dsl_summary.get("exam", {}).get("schemaValidated", False),
        "gradingValidated": dsl_summary.get("grading", {}).get("schemaValidated", False),
        "pptValidated": dsl_summary.get("ppt", {}).get("schemaValidated", False),
        "candidatePreviewSafe": candidate_safe,
        "reviewStatus": TaskStatus.WAITING_REVIEW.value if review_gated else "INVALID",
        "reviewRequired": review_required,
        "publishBlockedUntilApproved": publish_blocked,
        "blockingIssueTotal": content_quality.get("blockingIssueTotal", 0) if isinstance(content_quality, dict) else 0,
        "warningIssueTotal": content_quality.get("warningTotal", 0) if isinstance(content_quality, dict) else 0,
        "generatedDsl": dsl_summary,
        "safety": {
            "realLlmCalled": report.get("safety", {}).get("realLlmCalled", False),
            "secretsRead": report.get("safety", {}).get("secretsRead", False),
            "networkAccess": report.get("safety", {}).get("networkAccess", False),
            "sandboxExecuted": report.get("safety", {}).get("sandboxExecuted", False),
            "contestantCodeExecuted": report.get("safety", {}).get("contestantCodeExecuted", False),
            "unknownShellExecuted": report.get("safety", {}).get("unknownShellExecuted", False),
            "realCloudResourceCreated": report.get("safety", {}).get("realCloudResourceCreated", False),
            "realCloudResourceChanged": report.get("safety", {}).get("realCloudResourceChanged", False),
            "autoPublishAllowed": report.get("safety", {}).get("autoPublishAllowed", False),
            "realPublish": report.get("safety", {}).get("realPublish", False),
            "reviewBypassed": report.get("safety", {}).get("reviewBypassed", False),
        },
        "traceId": report.get("traceId"),
    }
    return summary


def _validate_offline_demo_summary(summary: dict[str, Any]) -> None:
    if summary.get("mode") != "offline":
        raise CliError(
            "VALIDATION_ERROR",
            "Offline Demo 报告格式错误",
            [{"field": "mode", "reason": "必须是 offline"}],
        )
    if summary.get("status") != "PASS":
        raise CliError(
            "VALIDATION_ERROR",
            "Offline Demo 校验失败",
            [{"field": "status", "reason": "离线主链路未通过"}],
        )
    if summary.get("blockingIssueTotal", 0) != 0:
        raise CliError(
            "VALIDATION_ERROR",
            "Offline Demo 存在质量阻塞项",
            [{"field": "blockingIssueTotal", "reason": "must be zero"}],
        )
    if summary.get("reviewStatus") != TaskStatus.WAITING_REVIEW.value:
        raise CliError(
            "VALIDATION_ERROR",
            "Offline Demo 必须保留人工审核状态",
            [{"field": "reviewStatus", "reason": "expected WAITING_REVIEW"}],
        )
    if summary.get("reviewRequired") is not True or summary.get("publishBlockedUntilApproved") is not True:
        raise CliError(
            "VALIDATION_ERROR",
            "Offline Demo 必须阻断未审核发布",
            [{"field": "reviewSummary", "reason": "review is required and publish must remain blocked"}],
        )
    safety = summary.get("safety", {})
    if any(
        bool(safety.get(field))
        for field in (
            "realLlmCalled",
            "secretsRead",
            "networkAccess",
            "sandboxExecuted",
            "contestantCodeExecuted",
            "unknownShellExecuted",
            "realCloudResourceCreated",
            "realCloudResourceChanged",
            "autoPublishAllowed",
            "realPublish",
            "reviewBypassed",
        )
    ):
        raise CliError(
            "VALIDATION_ERROR",
            "Offline Demo 包含不允许的真实执行标记",
            [{"field": "safety", "reason": "offline mode must remain local and review-gated"}],
        )


def _validate_phase2_report(report: dict[str, Any]) -> None:
    if report.get("phase") != "Phase 2":
        raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "phase", "reason": "必须是 Phase 2"}])
    mode = report.get("mode")
    if mode not in {PHASE2_MOCK_ONLY_MODE, PHASE2_REAL_LLM_MINIMAL_MODE, PHASE2_REAL_LLM_MODE, PHASE2_REAL_LLM_DEMO_MODE}:
        raise CliError(
            "VALIDATION_ERROR",
            "Phase 2 Workflow 报告格式错误",
            [{"field": "mode", "reason": f"必须是 {PHASE2_MOCK_ONLY_MODE}、{PHASE2_REAL_LLM_MINIMAL_MODE}、{PHASE2_REAL_LLM_MODE} 或 {PHASE2_REAL_LLM_DEMO_MODE}"}],
        )
    if report.get("workflowId") != PHASE2_WORKFLOW_ID:
        raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "workflowId", "reason": "不支持的 Workflow"}])
    generated = report.get("generatedDsl")
    if not isinstance(generated, dict) or set(generated) != {"lab", "exam", "grading", "ppt"}:
        raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "generatedDsl", "reason": "缺少 DSL 摘要"}])
    for kind, item in generated.items():
        if item.get("status") != TaskStatus.WAITING_REVIEW.value:
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": f"generatedDsl.{kind}.status", "reason": "必须等待人工审核"}])
    lab_context = report.get("labGenerationContext")
    if not isinstance(lab_context, dict):
        raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "labGenerationContext", "reason": "缺少 Lab 生成业务参数"}])
    if not lab_context.get("targetUsers") or int(lab_context.get("durationMinutes", 0)) <= 0:
        raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "labGenerationContext", "reason": "目标用户和课时必须有效"}])
    quality_signals = report.get("qualitySignals")
    if not isinstance(quality_signals, dict) or quality_signals.get("overall", {}).get("reviewRequired") is not True:
        raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "qualitySignals", "reason": "缺少审核质量信号"}])
    safety = report.get("safety", {})
    forbidden_fields = (
        "realAgentStarted",
        "realCloudResourceCreated",
        "realCloudResourceChanged",
        "sandboxExecuted",
        "contestantCodeExecuted",
        "unknownShellExecuted",
        "autoPublishAllowed",
        "realPublish",
        "reviewBypassed",
    )
    if any(bool(safety.get(field, False)) for field in forbidden_fields):
        raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety", "reason": "包含被禁用的真实执行标记"}])
    if mode == PHASE2_MOCK_ONLY_MODE:
        if any(bool(safety.get(field, False)) for field in ("realLlmCalled", "secretsRead", "networkAccess")):
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety", "reason": "Mock 模式不能包含真实 LLM 调用标记"}])
    if mode == PHASE2_REAL_LLM_MINIMAL_MODE:
        required_real_fields = ("realLlmCalled", "secretsRead", "networkAccess")
        if any(safety.get(field) is not True for field in required_real_fields):
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety", "reason": "真实 Lab 模式必须记录真实 LLM 调用边界"}])
        lab_provider = generated.get("lab", {}).get("provider", {})
        non_lab_providers = [generated.get(kind, {}).get("provider", {}) for kind in ("exam", "grading", "ppt")]
        if lab_provider.get("realLlmCalled") is not True:
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "generatedDsl.lab.provider.realLlmCalled", "reason": "真实 Lab 模式必须只在 Lab 生成中调用真实 LLM"}])
        if any(provider.get("realLlmCalled") is not False for provider in non_lab_providers):
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "generatedDsl", "reason": "Exam/Grading/PPT 在当前模式仍必须为 Mock"}])
    if mode == PHASE2_REAL_LLM_MODE:
        required_real_fields = ("realLlmCalled", "secretsRead", "networkAccess")
        if any(safety.get(field) is not True for field in required_real_fields):
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety", "reason": "真实 LLM 模式必须记录真实 LLM 调用边界"}])
        providers = {kind: generated.get(kind, {}).get("provider", {}) for kind in ("lab", "exam", "grading", "ppt")}
        if any(provider.get("realLlmCalled") is not True for provider in providers.values()):
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "generatedDsl", "reason": "真实 LLM 模式必须生成四类真实 DSL"}])
        if set(safety.get("realLlmGeneratedKinds", [])) != {"lab", "exam", "grading", "ppt"}:
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety.realLlmGeneratedKinds", "reason": "必须包含 lab/exam/grading/ppt"}])
        if int(safety.get("realLlmRequestCount", 0) or 0) != 4:
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety.realLlmRequestCount", "reason": "真实 LLM 模式应记录 4 次 DSL 请求"}])
    if mode == PHASE2_REAL_LLM_DEMO_MODE:
        required_real_fields = ("realLlmCalled", "secretsRead", "networkAccess")
        if any(safety.get(field) is not True for field in required_real_fields):
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety", "reason": "真实 Demo 模式必须记录真实 LLM 调用边界"}])
        providers = {kind: generated.get(kind, {}).get("provider", {}) for kind in ("lab", "exam", "grading", "ppt")}
        if any(provider.get("realLlmCalled") is not True for provider in providers.values()):
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "generatedDsl", "reason": "真实 Demo 模式必须生成四类真实 DSL"}])
        if set(safety.get("realLlmGeneratedKinds", [])) != {"lab", "exam", "grading", "ppt"}:
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety.realLlmGeneratedKinds", "reason": "必须包含 lab/exam/grading/ppt"}])
        if int(safety.get("realLlmRequestCount", 0) or 0) != 4:
            raise CliError("VALIDATION_ERROR", "Phase 2 Workflow 报告格式错误", [{"field": "safety.realLlmRequestCount", "reason": "演示模式应记录 4 次 DSL 请求"}])


def _validate_real_llm_demo_bundle(bundle: dict[str, Any]) -> None:
    if bundle.get("workflowId") != PHASE2_REAL_LLM_DEMO_BUNDLE_WORKFLOW_ID:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "workflowId", "reason": "不支持的 Bundle"}])
    if bundle.get("mode") != PHASE2_REAL_LLM_DEMO_BUNDLE_MODE:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "mode", "reason": "不支持的模式"}])
    generated = bundle.get("generatedDsl")
    if not isinstance(generated, dict) or set(generated) != {"lab", "exam", "grading", "ppt"}:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "generatedDsl", "reason": "缺少四类 DSL 摘要"}])
    for kind, summary in generated.items():
        if summary.get("status") != TaskStatus.WAITING_REVIEW.value:
            raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": f"generatedDsl.{kind}.status", "reason": "必须等待人工审核"}])
        if summary.get("schemaValidated") is not True:
            raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": f"generatedDsl.{kind}.schemaValidated", "reason": "必须通过 Schema 校验"}])
    candidate_preview = bundle.get("candidatePreview", {})
    if candidate_preview.get("answerVisibleToCandidate") is not False or candidate_preview.get("answersRemoved") is not True:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "candidatePreview", "reason": "候选人预览必须脱敏"}])
    safety = bundle.get("safety", {})
    if safety.get("realLlmCalled") is not True:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "safety.realLlmCalled", "reason": "Bundle 必须引用真实 LLM 产物"}])
    if safety.get("secretValueReturned") is not False or safety.get("secretValueLogged") is not False:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "safety.secretValue", "reason": "不得返回或记录密钥"}])
    if any(safety.get(field) is not False for field in ("realPublish", "autoPublishAllowed", "reviewBypassed", "contestantCodeExecuted", "commandExecuted", "pytestExecuted", "notebookExecuted", "unknownShellExecuted")):
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "safety", "reason": "包含被禁用的真实执行标记"}])
    evidence_demo = bundle.get("readonlyEvidenceDemo")
    if not isinstance(evidence_demo, dict):
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "readonlyEvidenceDemo", "reason": "缺少只读 evidence 演示层"}])
    if evidence_demo.get("doesNotModifySourceGrading") is not True:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "readonlyEvidenceDemo.doesNotModifySourceGrading", "reason": "必须声明不修改原始真实 Grading"}])
    if evidence_demo.get("safety", {}).get("contestantCodeExecuted") is not False:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "readonlyEvidenceDemo.safety", "reason": "不得执行选手代码"}])
    ppt_artifact = bundle.get("pptArtifact")
    if not isinstance(ppt_artifact, dict):
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "pptArtifact", "reason": "缺少 PPTX Artifact 摘要"}])
    if ppt_artifact.get("kind") != ArtifactKind.PPTX_FILE.value or ppt_artifact.get("status") != TaskStatus.WAITING_REVIEW.value:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "pptArtifact", "reason": "PPTX Artifact 必须等待人工审核"}])
    if ppt_artifact.get("autoPublishAllowed") is not False or ppt_artifact.get("realPublish") is not False:
        raise CliError("VALIDATION_ERROR", "真实 Demo Bundle 格式错误", [{"field": "pptArtifact.safety", "reason": "PPTX Artifact 不得自动发布"}])


def _dsl_summary(kind: str, path: Path, document: dict[str, Any], source: str) -> dict[str, Any]:
    metadata = document.get("metadata", {}) if isinstance(document, dict) else {}
    spec = document.get("spec", {}) if isinstance(document, dict) else {}
    summary: dict[str, Any] = {
        "kind": kind,
        "dslKind": document.get("kind"),
        "dslId": metadata.get("id"),
        "title": metadata.get("title"),
        "status": document.get("status"),
        "path": str(path),
        "schemaValidated": True,
        "reviewRequired": document.get("status") == TaskStatus.WAITING_REVIEW.value,
        "source": source,
    }
    if kind == "lab":
        summary.update(
            {
                "durationMinutes": metadata.get("durationMinutes"),
                "difficulty": metadata.get("difficulty"),
                "objectiveCount": len(spec.get("objectives", [])) if isinstance(spec.get("objectives"), list) else 0,
                "stepCount": len(spec.get("steps", [])) if isinstance(spec.get("steps"), list) else 0,
                "tags": metadata.get("tags", []),
            }
        )
    elif kind == "exam":
        questions = spec.get("questions", [])
        summary.update(
            {
                "sourceLabId": metadata.get("sourceLabId"),
                "questionType": spec.get("questionType"),
                "questionCount": len(questions) if isinstance(questions, list) else 0,
                "totalScore": spec.get("totalScore"),
                "answerVisibleToCandidate": False,
            }
        )
    elif kind == "grading":
        checks = spec.get("checks", [])
        assessment_plan = spec.get("assessmentPlan", [])
        check_types: dict[str, int] = {}
        if isinstance(checks, list):
            for check in checks:
                if isinstance(check, dict):
                    check_type = str(check.get("type"))
                    check_types[check_type] = check_types.get(check_type, 0) + 1
        summary.update(
            {
                "sourceExamId": metadata.get("sourceExamId"),
                "checkCount": len(checks) if isinstance(checks, list) else 0,
                "assessmentPlanCount": len(assessment_plan) if isinstance(assessment_plan, list) else 0,
                "totalScore": spec.get("totalScore"),
                "checkTypes": check_types,
                "sandboxRequiredBeforeRealExecution": True,
            }
        )
    elif kind == "ppt":
        slides = spec.get("slides", [])
        summary.update(
            {
                "audience": metadata.get("audience"),
                "durationMinutes": metadata.get("durationMinutes"),
                "slideCount": len(slides) if isinstance(slides, list) else 0,
                "artifactGenerated": False,
            }
        )
    return summary


def _candidate_preview_summary(preview: dict[str, Any], path: Path) -> dict[str, Any]:
    return {
        "kind": preview.get("kind"),
        "mode": preview.get("mode"),
        "sourceExamId": preview.get("sourceExamId"),
        "sourceStatus": preview.get("sourceStatus"),
        "questionCount": len(preview.get("questions", [])) if isinstance(preview.get("questions"), list) else 0,
        "totalScore": preview.get("totalScore"),
        "answersRemoved": preview.get("answersRemoved"),
        "answerVisibleToCandidate": preview.get("answerVisibleToCandidate"),
        "answerFieldsRemoved": preview.get("redaction", {}).get("answerFieldsRemoved"),
        "answerLeakDetected": preview.get("redaction", {}).get("answerLeakDetected"),
        "reviewRequired": preview.get("reviewRequired"),
        "path": str(path),
    }


def _readonly_demo_assessment_plan(check_id: str, check_type: str, runner: str, score: int, input_summary: str) -> dict[str, Any]:
    return {
        "checkId": check_id,
        "type": check_type,
        "runner": runner,
        "score": score,
        "inputSummary": input_summary,
        "executionPlan": {
            "strategy": "MOCK_PLAN_ONLY",
            "requiredLimits": {
                "cpu": "required",
                "memory": "required",
                "timeout": "30s",
                "network": "disabled_by_default",
                "filesystem": "isolated_workspace_required",
                "process": "limited",
            },
            "wouldRunInsideRealSandbox": True,
        },
        "mockEvidence": {"status": "MOCK_EVIDENCE_NOT_COLLECTED"},
        "riskLevel": "low",
        "sandboxRequiredBeforeRealExecution": True,
    }


def _build_readonly_evidence_demo_grading(
    *,
    lab: dict[str, Any],
    exam: dict[str, Any],
    grading: dict[str, Any],
) -> dict[str, Any]:
    exam_metadata = exam.get("metadata", {}) if isinstance(exam, dict) else {}
    grading_metadata = grading.get("metadata", {}) if isinstance(grading, dict) else {}
    title = grading_metadata.get("title") or exam_metadata.get("title") or "Real LLM Demo"
    return {
        "version": "1.0",
        "kind": "Grading",
        "metadata": {
            "id": "grading_real_llm_demo_readonly_evidence",
            "title": f"{title} - Readonly Evidence Demo",
            "sourceExamId": str(exam_metadata.get("id") or grading_metadata.get("sourceExamId") or "exam_real_llm_demo"),
        },
        "status": TaskStatus.WAITING_REVIEW.value,
        "spec": {
            "totalScore": 70,
            "timeoutSeconds": 30,
            "assessmentPlan": [
                _readonly_demo_assessment_plan(
                    "check_result_file",
                    "file_exists",
                    "FileExistsGrader",
                    30,
                    "Check that the demo submission contains result.csv for the real LLM generated exercise.",
                ),
                _readonly_demo_assessment_plan(
                    "check_accuracy_metric",
                    "json_field",
                    "JsonFieldGrader",
                    40,
                    "Check metrics.json $.accuracy equals 0.9 without executing contestant code.",
                ),
            ],
            "checks": [
                {
                    "id": "check_result_file",
                    "type": "file_exists",
                    "path": "result.csv",
                    "score": 30,
                },
                {
                    "id": "check_accuracy_metric",
                    "type": "json_field",
                    "path": "metrics.json",
                    "jsonPath": "$.accuracy",
                    "expectedValue": 0.9,
                    "score": 40,
                },
            ],
        },
    }


def _build_real_llm_demo_bundle(
    *,
    workflow_report_path: Path,
    lab_path: Path,
    exam_path: Path,
    grading_path: Path,
    ppt_path: Path,
    submission_path: Path,
    normalized_grading_output_path: Path,
    precheck_output_path: Path,
    readonly_report_output_path: Path,
    readonly_evidence_grading_output_path: Path,
    readonly_evidence_report_output_path: Path,
    candidate_preview_output_path: Path,
    pptx_output_path: Path,
    pptx_manifest_output_path: Path,
    pptx_preview_output_path: Path,
    pptx_preview_dir_path: Path,
    pptx_contact_sheet_output_path: Path,
    output_path: Path,
    reviewer: str,
    trace_id: str,
) -> dict[str, Any]:
    for field, path in (
        ("workflow-report", workflow_report_path),
        ("lab", lab_path),
        ("exam", exam_path),
        ("grading", grading_path),
        ("ppt", ppt_path),
    ):
        _ensure_file(path, field)
    workflow_report = _read_json(workflow_report_path)
    _validate_phase2_report(workflow_report)
    lab = _validate_yaml("lab", lab_path)
    exam = _validate_yaml("exam", exam_path)
    grading = _validate_yaml("grading", grading_path)
    ppt = _validate_yaml("ppt", ppt_path)
    if ppt.get("status") != TaskStatus.WAITING_REVIEW.value:
        raise CliError(
            "VALIDATION_ERROR",
            "真实 Demo PPTX Artifact 生成只接受 WAITING_REVIEW PPT DSL",
            [{"field": "ppt.status", "reason": "必须是 WAITING_REVIEW"}],
        )
    candidate_preview = build_exam_candidate_preview_from_file(exam_path, root=ROOT, trace_id=trace_id)
    _write_json(candidate_preview_output_path, candidate_preview)
    ppt_builder_workspace = _create_presentation_workspace("demo-bundle-ppt-dsl")
    try:
        builder_dsl_path = ppt_builder_workspace / "ppt-dsl.json"
        _write_json(builder_dsl_path, ppt)
        pptx_build = _run_pptx_artifact_builder(
            builder_dsl_path,
            pptx_output_path,
            pptx_manifest_output_path,
            pptx_preview_output_path,
            pptx_preview_dir_path,
            pptx_contact_sheet_output_path,
        )
    finally:
        shutil.rmtree(ppt_builder_workspace, ignore_errors=True)
    pptx_build["sourceDslPath"] = str(ppt_path)
    ppt_artifact = {
        "mode": "LOCAL_PPTX_ARTIFACT_POC",
        "kind": ArtifactKind.PPTX_FILE.value,
        "status": TaskStatus.WAITING_REVIEW.value,
        "path": str(pptx_output_path),
        "manifestPath": str(pptx_manifest_output_path),
        "previewPath": str(pptx_preview_output_path),
        "previewDir": str(pptx_preview_dir_path),
        "contactSheetPath": str(pptx_contact_sheet_output_path),
        "sourceDslPath": str(ppt_path),
        "sourceDslId": ppt.get("metadata", {}).get("id"),
        "title": f"{ppt.get('metadata', {}).get('title', 'PPT')} PPTX Artifact",
        "slideCount": pptx_build.get("slideCount"),
        "bytes": pptx_build.get("bytes"),
        "generator": pptx_build.get("generator"),
        "preview": pptx_build.get("preview", {}),
        "previewAvailable": pptx_build.get("preview", {}).get("previewAvailable", False),
        "firstSlidePreview": pptx_build.get("preview", {}).get("firstSlide", {}),
        "slidePreviews": pptx_build.get("preview", {}).get("slidePreviews", []),
        "contactSheet": pptx_build.get("preview", {}).get("contactSheet"),
        "reviewRequired": True,
        "autoPublishAllowed": False,
        "realPublish": False,
        "realLlmCalled": False,
        "newLlmRequestSent": False,
        "secretsRead": False,
        "networkAccess": False,
    }
    normalized = _normalize_real_llm_demo_grading(grading, exam)
    _write_json(normalized_grading_output_path, normalized["dsl"])
    normalized["dslPath"] = str(normalized_grading_output_path)
    precheck_report = _build_real_sandbox_precheck_report(normalized["dsl"], trace_id)
    precheck_report["reportPath"] = str(precheck_output_path)
    _write_json(precheck_output_path, precheck_report)
    readonly_report = _build_readonly_sandbox_report(normalized["dsl"], submission_path, trace_id)
    readonly_report["reportPath"] = str(readonly_report_output_path)
    readonly_report["reportDetail"] = build_grading_report_detail(readonly_report)
    _write_json(readonly_report_output_path, readonly_report)
    readonly_evidence_grading = _build_readonly_evidence_demo_grading(lab=lab, exam=exam, grading=grading)
    validate_dsl(readonly_evidence_grading, load_schema("grading", ROOT))
    _write_json(readonly_evidence_grading_output_path, readonly_evidence_grading)
    readonly_evidence_report = _build_readonly_sandbox_report(readonly_evidence_grading, submission_path, trace_id)
    readonly_evidence_report["reportPath"] = str(readonly_evidence_report_output_path)
    readonly_evidence_report["reportDetail"] = build_grading_report_detail(readonly_evidence_report)
    _write_json(readonly_evidence_report_output_path, readonly_evidence_report)
    workflow_safety = workflow_report.get("safety", {})
    provider_summaries = {}
    generated_from_report = workflow_report.get("generatedDsl", {})
    for kind in ("lab", "exam", "grading", "ppt"):
        provider = generated_from_report.get(kind, {}).get("provider", {})
        provider_summaries[kind] = {
            "providerId": provider.get("providerId"),
            "adapterId": provider.get("adapterId"),
            "mode": provider.get("mode"),
            "model": provider.get("model"),
            "realLlmCalled": provider.get("realLlmCalled"),
            "networkAccess": provider.get("networkAccess"),
            "requestCount": provider.get("requestCount"),
            "responseId": provider.get("responseId"),
            "providerCallAuditEventId": provider.get("providerCallAuditEventId"),
        }
    generated_dsl = {
        "lab": _dsl_summary("lab", lab_path, lab, "real_llm_demo_output"),
        "exam": _dsl_summary("exam", exam_path, exam, "real_llm_demo_output"),
        "grading": _dsl_summary("grading", grading_path, grading, "real_llm_demo_output"),
        "ppt": _dsl_summary("ppt", ppt_path, ppt, "real_llm_demo_output"),
    }
    generated_dsl["grading"]["normalizedPath"] = str(normalized_grading_output_path)
    generated_dsl["grading"]["normalization"] = normalized.get("normalization", {})
    generated_dsl["grading"]["normalizedCheckTypes"] = _dsl_summary(
        "grading",
        normalized_grading_output_path,
        normalized["dsl"],
        "normalized_real_llm_demo_output",
    ).get("checkTypes", {})
    generated_dsl["ppt"]["artifactGenerated"] = True
    generated_dsl["ppt"]["pptxPath"] = str(pptx_output_path)
    generated_dsl["ppt"]["pptxManifestPath"] = str(pptx_manifest_output_path)
    generated_dsl["ppt"]["pptxPreviewPath"] = str(pptx_preview_output_path)
    generated_dsl["ppt"]["pptxPreviewDir"] = str(pptx_preview_dir_path)
    generated_dsl["ppt"]["pptxContactSheetPath"] = str(pptx_contact_sheet_output_path)
    generated_dsl["ppt"]["pptxBytes"] = pptx_build.get("bytes")
    generated_dsl["ppt"]["pptxArtifactStatus"] = TaskStatus.WAITING_REVIEW.value
    generated_dsl["ppt"]["pptxPreviewAvailable"] = pptx_build.get("preview", {}).get("previewAvailable", False)
    generated_dsl["ppt"]["firstSlidePreview"] = pptx_build.get("preview", {}).get("firstSlide", {})
    generated_dsl["ppt"]["slidePreviewCount"] = len(pptx_build.get("preview", {}).get("slidePreviews", []))
    bundle = {
        "id": f"real_llm_demo_bundle_{uuid4().hex[:12]}",
        "workflowId": PHASE2_REAL_LLM_DEMO_BUNDLE_WORKFLOW_ID,
        "sourceWorkflowId": workflow_report.get("workflowId"),
        "phase": "Phase 2",
        "mode": PHASE2_REAL_LLM_DEMO_BUNDLE_MODE,
        "title": "Real LLM Demo Replay And Readonly Sandbox Bundle",
        "reviewer": reviewer,
        "input": workflow_report.get("input"),
        "sourceWorkflowReportPath": str(workflow_report_path),
        "reportPath": str(output_path),
        "provider": {
            "providerAdapter": workflow_report.get("providerAdapter"),
            "providerMode": workflow_report.get("providerMode"),
            "model": next((item.get("model") for item in provider_summaries.values() if item.get("model")), None),
            "realLlmGeneratedKinds": workflow_safety.get("realLlmGeneratedKinds", ["lab", "exam", "grading", "ppt"]),
            "realLlmRequestCount": workflow_safety.get("realLlmRequestCount"),
            "providers": provider_summaries,
        },
        "steps": [
            {"name": "load_real_llm_workflow_report", "status": "COMPLETED", "path": str(workflow_report_path)},
            {"name": "validate_real_llm_dsl", "status": "COMPLETED", "generatedKinds": list(generated_dsl)},
            {
                "name": "build_pptx_artifact",
                "status": "COMPLETED",
                "path": str(pptx_output_path),
                "manifestPath": str(pptx_manifest_output_path),
                "slideCount": pptx_build.get("slideCount"),
                "bytes": pptx_build.get("bytes"),
                "preview": pptx_build.get("preview", {}),
                "contactSheetPath": str(pptx_contact_sheet_output_path),
                "reviewRequired": True,
            },
            {"name": "build_candidate_preview", "status": "COMPLETED", "path": str(candidate_preview_output_path), "answerVisibleToCandidate": False},
            {"name": "normalize_grading_dsl", "status": "COMPLETED", "path": str(normalized_grading_output_path), "patchCount": len(normalized.get("normalization", {}).get("patches", []))},
            {"name": "real_sandbox_precheck", "status": "COMPLETED", "path": str(precheck_output_path), "readiness": precheck_report.get("readiness", {})},
            {
                "name": "readonly_sandbox_run",
                "status": "COMPLETED",
                "path": str(readonly_report_output_path),
                "executionSummary": readonly_report.get("executionSummary", {}),
                "score": readonly_report.get("score", {}),
            },
            {
                "name": "readonly_evidence_demo_run",
                "status": "COMPLETED",
                "gradingPath": str(readonly_evidence_grading_output_path),
                "reportPath": str(readonly_evidence_report_output_path),
                "executionSummary": readonly_evidence_report.get("executionSummary", {}),
                "score": readonly_evidence_report.get("score", {}),
            },
            {"name": "assemble_demo_bundle", "status": "COMPLETED", "path": str(output_path)},
        ],
        "generatedDsl": generated_dsl,
        "candidatePreview": _candidate_preview_summary(candidate_preview, candidate_preview_output_path),
        "pptArtifact": ppt_artifact,
        "gradingNormalization": {
            "mode": normalized.get("mode"),
            "schemaValidated": normalized.get("schemaValidated"),
            "dslId": normalized.get("dslId"),
            "outputPath": str(normalized_grading_output_path),
            "normalization": normalized.get("normalization", {}),
        },
        "sandboxPrecheck": {
            "mode": precheck_report.get("mode"),
            "reportPath": str(precheck_output_path),
            "readiness": precheck_report.get("readiness"),
            "summary": precheck_report.get("summary"),
            "safety": precheck_report.get("safety"),
        },
        "readonlySandbox": {
            "mode": readonly_report.get("mode"),
            "reportPath": str(readonly_report_output_path),
            "runner": readonly_report.get("runner"),
            "submissionRoot": readonly_report.get("submissionRoot"),
            "executionSummary": readonly_report.get("executionSummary"),
            "score": readonly_report.get("score"),
            "passed": readonly_report.get("passed"),
            "safety": readonly_report.get("safety"),
        },
        "readonlyEvidenceDemo": {
            "mode": readonly_evidence_report.get("mode"),
            "purpose": "Low-risk readable evidence demo; source real LLM grading remains unchanged.",
            "sourceGradingId": grading.get("metadata", {}).get("id"),
            "doesNotModifySourceGrading": True,
            "gradingPath": str(readonly_evidence_grading_output_path),
            "reportPath": str(readonly_evidence_report_output_path),
            "runner": readonly_evidence_report.get("runner"),
            "submissionRoot": readonly_evidence_report.get("submissionRoot"),
            "executionSummary": readonly_evidence_report.get("executionSummary"),
            "score": readonly_evidence_report.get("score"),
            "passed": readonly_evidence_report.get("passed"),
            "safety": readonly_evidence_report.get("safety"),
        },
        "reviewSummary": {
            "generatedStatus": TaskStatus.WAITING_REVIEW.value,
            "reviewRequired": True,
            "publishBlockedUntilApproved": True,
            "answerVisibleToCandidate": False,
            "autoPublishAllowed": False,
            "manualReviewRequired": True,
            "reviewHighlights": [
                "真实 LLM 已产出 Lab/Exam/Grading/PPT 四类 DSL",
                "四类 DSL 已通过本地 Schema 校验，状态仍为 WAITING_REVIEW",
                "候选人预览已脱敏，不返回标准答案",
                "Grading DSL 已归一化并通过真实沙箱前预检",
                "PPT DSL 已导出本地 PPTX Artifact，仍需人工审核",
                "只读沙箱仅执行文件/JSON 字段类检查，其它检查延期",
                "Readonly evidence demo 使用独立 Grading DSL 展示低风险自动评分证据，不篡改真实 Grading",
            ],
        },
        "acceptanceSignals": {
            "realLlmDslArtifactsPresent": True,
            "allGeneratedDslWaitingReview": all(
                summary.get("status") == TaskStatus.WAITING_REVIEW.value for summary in generated_dsl.values()
            ),
            "schemasValidated": True,
            "candidatePreviewAnswerSafe": candidate_preview.get("answerVisibleToCandidate") is False and candidate_preview.get("answersRemoved") is True,
            "gradingNormalized": normalized.get("schemaValidated") is True,
            "precheckReadyForManualSandboxReview": precheck_report.get("readiness", {}).get("status") == "READY_FOR_MANUAL_SANDBOX_REVIEW",
            "readonlySandboxExecuted": readonly_report.get("safety", {}).get("sandboxExecuted") is True,
            "readonlyEvidenceDemoExecuted": readonly_evidence_report.get("safety", {}).get("sandboxExecuted") is True,
            "readonlyEvidenceDemoEarnedScore": readonly_evidence_report.get("score", {}).get("earnedScore"),
            "pptxArtifactGenerated": pptx_output_path.exists() and pptx_output_path.stat().st_size > 0,
            "pptxArtifactWaitingReview": ppt_artifact.get("status") == TaskStatus.WAITING_REVIEW.value,
            "contestantCodeExecuted": False,
            "realPublish": False,
        },
        "safety": {
            "realLlmCalled": True,
            "replayedExistingLlmArtifacts": True,
            "newLlmRequestSent": False,
            "secretsRead": False,
            "secretValueReturned": False,
            "secretValueLogged": False,
            "networkAccess": False,
            "pptxArtifactGenerated": True,
            "pptxArtifactAutoPublishAllowed": False,
            "sandboxExecuted": (
                readonly_report.get("safety", {}).get("sandboxExecuted") is True
                or readonly_evidence_report.get("safety", {}).get("sandboxExecuted") is True
            ),
            "readonlyOnly": (
                readonly_report.get("safety", {}).get("readonlyOnly") is True
                and readonly_evidence_report.get("safety", {}).get("readonlyOnly") is True
            ),
            "contestantCodeExecuted": False,
            "commandExecuted": False,
            "pytestExecuted": False,
            "notebookExecuted": False,
            "unknownShellExecuted": False,
            "autoPublishAllowed": False,
            "realPublish": False,
            "reviewBypassed": False,
        },
        "traceId": trace_id,
    }
    _validate_real_llm_demo_bundle(bundle)
    return bundle


def _summarize_real_llm_demo_bundle(bundle: dict[str, Any]) -> dict[str, Any]:
    return {
        "workflowId": bundle.get("workflowId"),
        "mode": bundle.get("mode"),
        "sourceWorkflowId": bundle.get("sourceWorkflowId"),
        "reportPath": bundle.get("reportPath"),
        "generatedDsl": {
            kind: {
                "dslId": item.get("dslId"),
                "title": item.get("title"),
                "status": item.get("status"),
                "path": item.get("path"),
                "schemaValidated": item.get("schemaValidated"),
            }
            for kind, item in bundle.get("generatedDsl", {}).items()
        },
        "candidatePreview": bundle.get("candidatePreview"),
        "pptArtifact": bundle.get("pptArtifact"),
        "readonlySandbox": {
            "mode": bundle.get("readonlySandbox", {}).get("mode"),
            "executionSummary": bundle.get("readonlySandbox", {}).get("executionSummary"),
            "score": bundle.get("readonlySandbox", {}).get("score"),
            "passed": bundle.get("readonlySandbox", {}).get("passed"),
        },
        "readonlyEvidenceDemo": {
            "mode": bundle.get("readonlyEvidenceDemo", {}).get("mode"),
            "gradingPath": bundle.get("readonlyEvidenceDemo", {}).get("gradingPath"),
            "reportPath": bundle.get("readonlyEvidenceDemo", {}).get("reportPath"),
            "executionSummary": bundle.get("readonlyEvidenceDemo", {}).get("executionSummary"),
            "score": bundle.get("readonlyEvidenceDemo", {}).get("score"),
            "passed": bundle.get("readonlyEvidenceDemo", {}).get("passed"),
            "doesNotModifySourceGrading": bundle.get("readonlyEvidenceDemo", {}).get("doesNotModifySourceGrading"),
        },
        "acceptanceSignals": bundle.get("acceptanceSignals"),
        "safety": bundle.get("safety"),
        "traceId": bundle.get("traceId"),
    }


def _save_real_llm_demo_bundle_records(
    store: JsonTaskStore,
    *,
    bundle: dict[str, Any],
    output_path: Path,
    workflow_report_path: Path,
    reviewer: str,
    trace_id: str,
) -> dict[str, Any]:
    artifact = _save_artifact(
        store,
        kind=ArtifactKind.WORKFLOW_REPORT,
        path=str(output_path),
        title="Real LLM Demo Replay And Readonly Sandbox Bundle",
        status=ArtifactStatus.COMPLETED,
        trace_id=trace_id,
        source_ref=str(workflow_report_path),
        metadata={
            "workflowId": PHASE2_REAL_LLM_DEMO_BUNDLE_WORKFLOW_ID,
            "sourceWorkflowId": bundle.get("sourceWorkflowId"),
            "reviewRequired": True,
            "generatedDsl": bundle.get("generatedDsl", {}),
            "candidatePreview": bundle.get("candidatePreview", {}),
            "pptArtifact": bundle.get("pptArtifact", {}),
            "readonlySandbox": bundle.get("readonlySandbox", {}),
            "readonlyEvidenceDemo": bundle.get("readonlyEvidenceDemo", {}),
            "acceptanceSignals": bundle.get("acceptanceSignals", {}),
        },
        mode=bundle["mode"],
        real_llm_called=True,
        sandbox_executed=bool(bundle.get("safety", {}).get("sandboxExecuted", False)),
        contestant_code_executed=False,
        real_publish=False,
    )
    workflow_run = create_workflow_run(
        workflow_id=PHASE2_REAL_LLM_DEMO_BUNDLE_WORKFLOW_ID,
        input_ref=str(workflow_report_path),
        reviewer=reviewer,
        trace_id=trace_id,
        report_path=str(output_path),
        steps=_workflow_steps_from_report(bundle),
    )
    workflow_run.mode = bundle["mode"]
    workflow_run.realLlmCalled = True
    workflow_run.sandboxExecuted = bool(bundle.get("safety", {}).get("sandboxExecuted", False))
    workflow_run.contestantCodeExecuted = False
    workflow_run.realPublish = False
    store.save_workflow_run(workflow_run)
    artifact_record = store.get_artifact(artifact["id"])
    linked_artifact = artifact
    if artifact_record is not None:
        artifact_record.workflowRunId = workflow_run.id
        store.save_artifact(artifact_record)
        linked_artifact = artifact_record.to_dict()
    return {"workflowRun": workflow_run.to_dict(), "artifact": linked_artifact}


def _build_real_demo_acceptance_step(
    *,
    step_id: str,
    title: str,
    source: str,
    passed: bool,
    expected_signal: str,
    route: str | None = None,
    command: str | None = None,
) -> dict[str, Any]:
    step = {
        "id": step_id,
        "title": title,
        "source": source,
        "passed": passed,
        "expectedSignal": expected_signal,
    }
    if route is not None:
        step["route"] = route
    if command is not None:
        step["command"] = command
    return step


def _build_real_llm_demo_acceptance_summary(bundle_path: Path, output_path: Path | None = None) -> dict[str, Any]:
    _ensure_file(bundle_path, "bundle")
    bundle = _read_json(bundle_path)
    _validate_real_llm_demo_bundle(bundle)

    frontend_data_path = ROOT / "frontend" / "mock-data.json"
    mcp_manifest_path = ROOT / "mcp-server" / "tools.manifest.json"
    _ensure_file(frontend_data_path, "frontendMockData")
    _ensure_file(mcp_manifest_path, "mcpManifest")
    frontend_data = _read_json(frontend_data_path)
    mcp_manifest = _read_json(mcp_manifest_path)

    real_demo = frontend_data.get("realDemoPrototype", {})
    review_center = frontend_data.get("reviewCenterPrototype", {})
    grading_report = frontend_data.get("gradingReportPrototype", {})
    real_demo_review_queue = review_center.get("realDemoReviewQueue", {})
    readonly_report_detail = real_demo.get("readonlyEvidenceDemo", {}).get("reportDetail", {})
    controlled_docker_evidence = real_demo.get("controlledDockerEvidenceDemo", {})
    notebook_static_evidence = review_center.get("notebookEvidenceReviewPlan", {})
    grading_readonly_summary = grading_report.get("readonlyReportDetailSummary", {})
    tools = mcp_manifest.get("tools", [])
    review_task_tool = next((tool for tool in tools if tool.get("name") == "get_review_task_summary"), {})
    mcp_real_demo_contract = (
        review_task_tool.get("outputContract", {}).get("realDemoReviewQueue", {})
        if isinstance(review_task_tool, dict)
        else {}
    )

    generated_dsl = bundle.get("generatedDsl", {})
    acceptance_signals = bundle.get("acceptanceSignals", {})
    safety = bundle.get("safety", {})
    candidate_preview = bundle.get("candidatePreview", {})
    readonly_evidence_demo = bundle.get("readonlyEvidenceDemo", {})
    ppt_artifact = bundle.get("pptArtifact", {})
    core_business_path = real_demo.get("coreBusinessDemoPath", {})

    dsl_validated_total = sum(
        1
        for summary in generated_dsl.values()
        if summary.get("status") == TaskStatus.WAITING_REVIEW.value and summary.get("schemaValidated") is True
    )
    review_queue_items = real_demo_review_queue.get("items", [])
    mcp_required_fields = set(mcp_real_demo_contract.get("requiredFields", []))
    mcp_contract_ready = {
        "enabled",
        "component",
        "source",
        "route",
        "taskTotal",
        "waitingReviewTotal",
        "schemaValidatedTotal",
        "readonlyEvidenceReportDetailSource",
        "readonlyEvidenceCollectedTotal",
        "items",
        "autoApproveAllowed",
        "batchStateChangeAllowed",
        "realPublishAllowed",
    }.issubset(mcp_required_fields)
    readonly_evidence_collected_total = int(
        real_demo_review_queue.get("readonlyEvidenceCollectedTotal")
        or readonly_report_detail.get("readonlyEvidence", {}).get("collectedTotal")
        or 0
    )
    controlled_score = int(controlled_docker_evidence.get("score", {}).get("earnedScore") or 0)
    controlled_total = int(controlled_docker_evidence.get("score", {}).get("totalScore") or 0)
    notebook_static_score = int(notebook_static_evidence.get("earnedScore") or 0)
    notebook_static_total = int(notebook_static_evidence.get("totalStaticNotebookScore") or 0)
    grading_evidence_coverage = {
        "status": "GRADING_EVIDENCE_COVERAGE_COMPLETE"
        if controlled_score + notebook_static_score == controlled_total + notebook_static_total == 100
        else "GRADING_EVIDENCE_COVERAGE_PARTIAL",
        "source": "controlledDockerEvidenceDemo + notebookEvidenceReviewPlan",
        "controlledDockerReportPath": controlled_docker_evidence.get("reportPath"),
        "notebookStaticReportPath": notebook_static_evidence.get("staticEvidenceReportPath"),
        "coveredCheckIds": list(controlled_docker_evidence.get("checks", []))
        and [check.get("id") for check in controlled_docker_evidence.get("checks", [])]
        or list(controlled_docker_evidence.get("coveredCheckIds", []))
        if controlled_docker_evidence.get("coveredCheckIds")
        else ["check_q1", "check_q4"],
        "staticNotebookCheckIds": list(notebook_static_evidence.get("remainingCheckIds", [])),
        "coveredCheckTypes": list(controlled_docker_evidence.get("runner", {}).get("supportedCheckTypes", []))
        + list(notebook_static_evidence.get("checkTypes", [])),
        "controlledDockerScore": controlled_score,
        "controlledDockerTotal": controlled_total,
        "notebookStaticScore": notebook_static_score,
        "notebookStaticTotal": notebook_static_total,
        "earnedScore": controlled_score + notebook_static_score,
        "totalScore": controlled_total + notebook_static_total,
        "coveragePercent": 100
        if controlled_total + notebook_static_total == 0
        else round((controlled_score + notebook_static_score) * 100 / (controlled_total + notebook_static_total), 2),
        "manualReviewRequired": True,
        "autoApproveAllowed": False,
        "realPublishAllowed": False,
        "safety": {
            "sourceGradingModified": False,
            "hostExecutionAllowed": False,
            "networkEnabled": False,
            "notebookKernelStarted": False,
            "notebookExecuted": False,
            "autoApproveAllowed": False,
            "realPublishAllowed": False,
        },
    }
    ppt_page_review_action_visible = any(
        item.get("artifactKind") == "PPT_DSL_AND_PPTX_FILE" and item.get("pptPageReviewActionVisible") is True
        for item in review_queue_items
    )
    steps = [
        _build_real_demo_acceptance_step(
            step_id="real_demo_bundle_valid",
            title="Real LLM demo bundle validated",
            source=str(bundle_path),
            passed=dsl_validated_total == 4 and acceptance_signals.get("allGeneratedDslWaitingReview") is True,
            expected_signal="Four generated DSL artifacts are schema validated and WAITING_REVIEW.",
            command=f"python lab_cli.py phase2 demo-bundle report --file {bundle_path}",
        ),
        _build_real_demo_acceptance_step(
            step_id="real_demo_page_visible",
            title="Real demo page links core business path",
            source="frontend/mock-data.json.realDemoPrototype.coreBusinessDemoPath",
            passed=core_business_path.get("component") == "CoreBusinessDemoPath"
            and core_business_path.get("manualReviewRequired") is True,
            expected_signal="CoreBusinessDemoPath is available and keeps manual review required.",
            route="/real-demo",
        ),
        _build_real_demo_acceptance_step(
            step_id="review_center_real_demo_queue_visible",
            title="Review center exposes real demo queue",
            source="frontend/mock-data.json.reviewCenterPrototype.realDemoReviewQueue",
            passed=real_demo_review_queue.get("component") == "RealDemoReviewQueue"
            and real_demo_review_queue.get("taskTotal") == 4
            and real_demo_review_queue.get("waitingReviewTotal") == 4
            and real_demo_review_queue.get("batchStateChangeAllowed") is False,
            expected_signal="Review queue shows four WAITING_REVIEW artifacts and disables batch state changes.",
            route="/review-center",
            command="python lab_cli.py review batch-summary",
        ),
        _build_real_demo_acceptance_step(
            step_id="mcp_get_review_task_summary_contract_visible",
            title="MCP review task summary contract includes real demo queue",
            source="mcp-server/tools.manifest.json.get_review_task_summary.outputContract.realDemoReviewQueue",
            passed=mcp_contract_ready,
            expected_signal="MCP output contract requires realDemoReviewQueue and fixed safety fields.",
            command='python lab_cli.py mcp call --tool get_review_task_summary --arguments "{}"',
        ),
        _build_real_demo_acceptance_step(
            step_id="grading_report_readonly_report_detail_visible",
            title="Grading report shows readonly evidence detail",
            source="frontend/mock-data.json.realDemoPrototype.readonlyEvidenceDemo.reportDetail",
            passed=readonly_report_detail.get("readonlyEvidence", {}).get("status") == "COLLECTED"
            and grading_readonly_summary.get("source") == "realDemoPrototype.readonlyEvidenceDemo.reportDetail",
            expected_signal="Readonly evidence report detail is collected and reused by grading report.",
            route="/grading/:id/report",
        ),
        _build_real_demo_acceptance_step(
            step_id="grading_evidence_coverage_complete",
            title="Grading evidence coverage reaches 100 points",
            source="controlledDockerEvidenceDemo + notebookEvidenceReviewPlan",
            passed=grading_evidence_coverage["status"] == "GRADING_EVIDENCE_COVERAGE_COMPLETE"
            and grading_evidence_coverage["earnedScore"] == grading_evidence_coverage["totalScore"] == 100
            and grading_evidence_coverage["autoApproveAllowed"] is False,
            expected_signal="Controlled Docker evidence covers 40 points and static Notebook evidence covers 60 points.",
            route="/grading/:id/report",
            command="python lab_cli.py grade sandbox-run --grading examples/output/mimo-real-demo-notebook-static-plan.json --submission examples/submissions/real-demo-notebook --output examples/output/mimo-real-demo-notebook-static-report.json",
        ),
        _build_real_demo_acceptance_step(
            step_id="ppt_artifact_review_action_visible",
            title="PPT artifact is visible for page-level review",
            source="frontend/mock-data.json.reviewCenterPrototype.realDemoReviewQueue.items[ppt]",
            passed=ppt_page_review_action_visible and ppt_artifact.get("status") == TaskStatus.WAITING_REVIEW.value,
            expected_signal="PPTX artifact remains WAITING_REVIEW and page review action is visible.",
            route="/ppt/:id/review",
        ),
    ]
    passed_count = sum(1 for step in steps if step["passed"])
    total = len(steps)
    summary = {
        "workflowId": "phase2_real_llm_demo_acceptance",
        "mode": "REAL_LLM_DEMO_ACCEPTANCE_STATIC",
        "sourceBundleMode": bundle.get("mode"),
        "bundlePath": str(bundle_path),
        "outputPath": str(output_path) if output_path is not None else None,
        "route": real_demo_review_queue.get("route") or core_business_path.get("route"),
        "sources": {
            "bundle": str(bundle_path),
            "realDemo": "frontend/mock-data.json.realDemoPrototype",
            "reviewCenter": "frontend/mock-data.json.reviewCenterPrototype.realDemoReviewQueue",
            "reviewTaskSummary": "reviewTaskSummary.realDemoReviewQueue",
            "mcpContract": "mcp-server/tools.manifest.json.get_review_task_summary.outputContract.realDemoReviewQueue",
            "gradingReport": "frontend/mock-data.json.gradingReportPrototype.readonlyReportDetailSummary",
        },
        "signals": {
            "dslValidatedTotal": dsl_validated_total,
            "waitingReviewDslTotal": sum(
                1 for summary in generated_dsl.values() if summary.get("status") == TaskStatus.WAITING_REVIEW.value
            ),
            "realDemoReviewQueueTaskTotal": real_demo_review_queue.get("taskTotal"),
            "reviewCenterLinked": real_demo_review_queue.get("component") == "RealDemoReviewQueue",
            "mcpOutputContractIncludesRealDemoReviewQueue": mcp_contract_ready,
            "readonlyEvidenceCollectedTotal": readonly_evidence_collected_total,
            "readonlyEvidenceDemoEarnedScore": readonly_evidence_demo.get("score", {}).get("earnedScore"),
            "controlledDockerEvidenceEarnedScore": controlled_score,
            "notebookStaticEvidenceEarnedScore": notebook_static_score,
            "gradingEvidenceCoverageEarnedScore": grading_evidence_coverage["earnedScore"],
            "gradingEvidenceCoverageTotalScore": grading_evidence_coverage["totalScore"],
            "gradingEvidenceCoveragePercent": grading_evidence_coverage["coveragePercent"],
            "gradingEvidenceCoverageStatus": grading_evidence_coverage["status"],
            "pptxArtifactGenerated": acceptance_signals.get("pptxArtifactGenerated"),
            "pptPageReviewActionVisible": ppt_page_review_action_visible,
            "reviewRequiredBeforePublish": real_demo_review_queue.get("manualReviewRequired") is True
            and bundle.get("reviewSummary", {}).get("publishBlockedUntilApproved") is True,
            "candidatePreviewAnswerSafe": candidate_preview.get("answerVisibleToCandidate") is False
            and candidate_preview.get("answersRemoved") is True,
            "answerVisibleToCandidate": candidate_preview.get("answerVisibleToCandidate"),
        },
        "safety": {
            "realLlmCalledInSourceBundle": safety.get("realLlmCalled") is True,
            "newLlmRequestSent": False,
            "secretsRead": False,
            "networkAccess": False,
            "autoApproveAllowed": real_demo_review_queue.get("autoApproveAllowed") is True,
            "batchStateChangeAllowed": real_demo_review_queue.get("batchStateChangeAllowed") is True,
            "realPublishAllowed": real_demo_review_queue.get("realPublishAllowed") is True,
            "contestantCodeExecuted": False,
            "commandExecuted": False,
            "pytestExecuted": False,
            "notebookExecuted": False,
        },
        "gradingEvidenceCoverage": grading_evidence_coverage,
        "steps": steps,
        "acceptance": {
            "passed": passed_count == total,
            "passedCount": passed_count,
            "total": total,
            "failedStepIds": [step["id"] for step in steps if not step["passed"]],
        },
        "recommendedCommands": [
            "start .\\frontend\\real-demo.html",
            "start .\\frontend\\review-center.html",
            "python lab_cli.py review batch-summary",
            'python lab_cli.py mcp call --tool get_review_task_summary --arguments "{}"',
            "start .\\frontend\\grading-report.html",
        ],
    }
    if summary["safety"]["autoApproveAllowed"] or summary["safety"]["batchStateChangeAllowed"] or summary["safety"]["realPublishAllowed"]:
        summary["acceptance"]["passed"] = False
        summary["acceptance"]["failedStepIds"].append("safety_publish_boundaries")
    return summary


def _build_real_demo_checklist_section(
    *,
    section_id: str,
    title: str,
    status: str,
    passed: bool,
    source: str,
    evidence: dict[str, Any],
    route: str | None = None,
    command: str | None = None,
) -> dict[str, Any]:
    section = {
        "id": section_id,
        "title": title,
        "status": status,
        "passed": passed,
        "source": source,
        "evidence": evidence,
    }
    if route is not None:
        section["route"] = route
    if command is not None:
        section["command"] = command
    return section


def _build_real_llm_demo_checklist(
    *,
    bundle_path: Path,
    acceptance_summary_path: Path,
    output_path: Path | None = None,
) -> dict[str, Any]:
    _ensure_file(bundle_path, "bundle")
    _ensure_file(acceptance_summary_path, "acceptanceSummary")
    bundle = _read_json(bundle_path)
    acceptance_summary = _read_json(acceptance_summary_path)
    _validate_real_llm_demo_bundle(bundle)

    acceptance = acceptance_summary.get("acceptance", {})
    signals = acceptance_summary.get("signals", {})
    acceptance_safety = acceptance_summary.get("safety", {})
    grading_evidence_coverage = acceptance_summary.get("gradingEvidenceCoverage", {})
    generated_dsl = bundle.get("generatedDsl", {})
    candidate_preview = bundle.get("candidatePreview", {})
    readonly_evidence_demo = bundle.get("readonlyEvidenceDemo", {})
    ppt_artifact = bundle.get("pptArtifact", {})
    steps = acceptance_summary.get("steps", [])

    waiting_review_dsl = [
        {
            "kind": kind,
            "path": summary.get("path"),
            "status": summary.get("status"),
            "schemaValidated": summary.get("schemaValidated") is True,
        }
        for kind, summary in generated_dsl.items()
    ]
    dsl_ready = len(waiting_review_dsl) == 4 and all(
        item["status"] == TaskStatus.WAITING_REVIEW.value and item["schemaValidated"] is True
        for item in waiting_review_dsl
    )
    checklist_safety = {
        "sourceBundleRealLlmCalled": bool(bundle.get("safety", {}).get("realLlmCalled")),
        "newLlmRequestSent": False,
        "secretsRead": False,
        "networkAccess": False,
        "sandboxExecutedByChecklist": False,
        "commandExecutedByChecklist": False,
        "pytestExecutedByChecklist": False,
        "notebookExecutedByChecklist": False,
        "contestantCodeExecutedByChecklist": False,
        "autoApproveAllowed": False,
        "batchStateChangeAllowed": False,
        "realPublishAllowed": False,
    }
    report_command = f"python lab_cli.py phase2 demo-bundle report --file {bundle_path}"
    acceptance_command = (
        f"python lab_cli.py phase2 demo-bundle acceptance --bundle {bundle_path} --output {acceptance_summary_path}"
    )
    checklist_command = (
        f"python lab_cli.py phase2 demo-bundle checklist --bundle {bundle_path} "
        f"--acceptance-summary {acceptance_summary_path} --output {output_path}"
    )

    sections = [
        _build_real_demo_checklist_section(
            section_id="generated_dsl",
            title="Generated DSL artifacts are ready for manual review",
            status="WAITING_REVIEW",
            passed=dsl_ready and signals.get("dslValidatedTotal") == 4,
            source=str(bundle_path),
            evidence={
                "dslTotal": len(waiting_review_dsl),
                "waitingReviewDslTotal": signals.get("waitingReviewDslTotal"),
                "items": waiting_review_dsl,
            },
            route="/real-demo",
            command=report_command,
        ),
        _build_real_demo_checklist_section(
            section_id="candidate_preview",
            title="Candidate preview hides answers",
            status="CANDIDATE_SAFE",
            passed=candidate_preview.get("answersRemoved") is True
            and candidate_preview.get("answerVisibleToCandidate") is False,
            source="bundle.candidatePreview",
            evidence={
                "answersRemoved": candidate_preview.get("answersRemoved"),
                "answerVisibleToCandidate": candidate_preview.get("answerVisibleToCandidate"),
                "standardAnswerRevealToCandidate": candidate_preview.get("standardAnswerRevealToCandidate"),
            },
            route="/real-demo",
        ),
        _build_real_demo_checklist_section(
            section_id="grading_evidence_coverage",
            title="Grading evidence coverage reaches 100 points",
            status=grading_evidence_coverage.get("status", "UNKNOWN"),
            passed=grading_evidence_coverage.get("earnedScore") == grading_evidence_coverage.get("totalScore") == 100
            and grading_evidence_coverage.get("autoApproveAllowed") is False,
            source="acceptanceSummary.gradingEvidenceCoverage",
            evidence={
                "controlledDockerScore": grading_evidence_coverage.get("controlledDockerScore"),
                "controlledDockerTotal": grading_evidence_coverage.get("controlledDockerTotal"),
                "notebookStaticScore": grading_evidence_coverage.get("notebookStaticScore"),
                "notebookStaticTotal": grading_evidence_coverage.get("notebookStaticTotal"),
                "earnedScore": grading_evidence_coverage.get("earnedScore"),
                "totalScore": grading_evidence_coverage.get("totalScore"),
                "coveragePercent": grading_evidence_coverage.get("coveragePercent"),
                "coveredCheckIds": grading_evidence_coverage.get("coveredCheckIds", []),
                "staticNotebookCheckIds": grading_evidence_coverage.get("staticNotebookCheckIds", []),
                "manualReviewRequired": grading_evidence_coverage.get("manualReviewRequired") is True,
                "autoApproveAllowed": grading_evidence_coverage.get("autoApproveAllowed") is True,
            },
            route="/grading/:id/report",
        ),
        _build_real_demo_checklist_section(
            section_id="pptx_artifact",
            title="PPTX artifact remains visible for page-level review",
            status=ppt_artifact.get("status", "UNKNOWN"),
            passed=ppt_artifact.get("status") == TaskStatus.WAITING_REVIEW.value
            and ppt_artifact.get("autoPublishAllowed") is False,
            source="bundle.pptArtifact",
            evidence={
                "path": ppt_artifact.get("path"),
                "manifestPath": ppt_artifact.get("manifestPath"),
                "previewAvailable": ppt_artifact.get("preview", {}).get("previewAvailable"),
                "slideCount": ppt_artifact.get("slideCount"),
                "autoPublishAllowed": ppt_artifact.get("autoPublishAllowed"),
                "realPublish": ppt_artifact.get("realPublish"),
            },
            route="/ppt/:id/review",
        ),
        _build_real_demo_checklist_section(
            section_id="review_and_mcp",
            title="Review center and MCP summary expose the same demo queue",
            status="VISIBLE",
            passed=signals.get("realDemoReviewQueueTaskTotal") == 4
            and signals.get("mcpOutputContractIncludesRealDemoReviewQueue") is True,
            source="acceptanceSummary.steps",
            evidence={
                "realDemoReviewQueueTaskTotal": signals.get("realDemoReviewQueueTaskTotal"),
                "mcpOutputContractIncludesRealDemoReviewQueue": signals.get(
                    "mcpOutputContractIncludesRealDemoReviewQueue"
                ),
                "stepIds": [step.get("id") for step in steps],
                "failedStepIds": acceptance.get("failedStepIds", []),
            },
            route="/review-center",
            command='python lab_cli.py mcp call --tool get_review_task_summary --arguments "{}"',
        ),
        _build_real_demo_checklist_section(
            section_id="safety_boundaries",
            title="Checklist is read-only and keeps publish boundaries closed",
            status="READONLY_BOUNDARIES_CLOSED",
            passed=all(
                checklist_safety[key] is False
                for key in [
                    "newLlmRequestSent",
                    "secretsRead",
                    "networkAccess",
                    "sandboxExecutedByChecklist",
                    "commandExecutedByChecklist",
                    "autoApproveAllowed",
                    "batchStateChangeAllowed",
                    "realPublishAllowed",
                ]
            )
            and acceptance_safety.get("realPublishAllowed") is False,
            source="acceptanceSummary.safety",
            evidence=checklist_safety,
        ),
    ]
    passed_sections = sum(1 for section in sections if section["passed"])
    total_sections = len(sections)
    acceptance_passed = acceptance.get("passed") is True
    return {
        "component": "RealDemoOneClickChecklist",
        "mode": "REAL_LLM_DEMO_CHECKLIST_STATIC",
        "source": "phase2 demo-bundle checklist",
        "bundlePath": str(bundle_path),
        "acceptanceSummaryPath": str(acceptance_summary_path),
        "checklistPath": str(output_path) if output_path is not None else None,
        "route": acceptance_summary.get("route"),
        "summary": {
            "readyForDemo": acceptance_passed and passed_sections == total_sections,
            "acceptancePassed": acceptance_passed,
            "acceptancePassedCount": acceptance.get("passedCount"),
            "acceptanceTotal": acceptance.get("total"),
            "failedStepIds": acceptance.get("failedStepIds", []),
            "sectionPassedCount": passed_sections,
            "sectionTotal": total_sections,
            "waitingReviewDslTotal": signals.get("waitingReviewDslTotal"),
            "readonlyEvidenceCollectedTotal": signals.get("readonlyEvidenceCollectedTotal"),
            "gradingEvidenceCoverageEarnedScore": grading_evidence_coverage.get("earnedScore"),
            "gradingEvidenceCoverageTotalScore": grading_evidence_coverage.get("totalScore"),
            "gradingEvidenceCoverageStatus": grading_evidence_coverage.get("status"),
            "pptxArtifactGenerated": signals.get("pptxArtifactGenerated"),
            "manualReviewRequired": True,
            "autoApproveAllowed": False,
            "realPublishAllowed": False,
        },
        "sections": sections,
        "recommendedDemoOrder": [
            "/real-demo",
            "/review-center",
            "/ppt/:id/review",
            "/grading/:id/report",
            "python lab_cli.py review batch-summary",
            'python lab_cli.py mcp call --tool get_review_task_summary --arguments "{}"',
        ],
        "safeCommands": [
            report_command,
            acceptance_command,
            checklist_command,
            "start .\\frontend\\real-demo.html",
            "start .\\frontend\\review-center.html",
            "start .\\frontend\\grading-report.html",
        ],
        "blockedActions": [
            "newRealLlmRequest",
            "secretRead",
            "networkAccess",
            "executeGradingCommand",
            "runRealPytest",
            "executeNotebook",
            "executeContestantCode",
            "standardAnswerRevealToCandidate",
            "autoApprove",
            "batchStateChange",
            "autoPublish",
            "realPublish",
        ],
        "safety": checklist_safety,
        "readonlyEvidenceSummary": {
            "doesNotModifySourceGrading": readonly_evidence_demo.get("doesNotModifySourceGrading"),
            "executed": readonly_evidence_demo.get("executionSummary", {}).get("executed"),
            "earnedScore": readonly_evidence_demo.get("score", {}).get("earnedScore"),
            "reportPath": readonly_evidence_demo.get("reportPath"),
        },
    }


def _approve_task_for_real_dsl_demo_close_loop(
    store: JsonTaskStore,
    *,
    task_id: str,
    reviewer: str,
    trace_id: str,
) -> dict[str, Any]:
    task = store.get(task_id)
    if task is None:
        raise CliError("NOT_FOUND", "AI Task 不存在", [{"field": "taskId", "reason": "未找到任务"}])
    if task.status == TaskStatus.APPROVED:
        return {
            "task": task.to_dict(),
            "alreadyApproved": True,
            "auditEvent": None,
            "operationAuditEvent": None,
        }
    if task.status != TaskStatus.WAITING_REVIEW:
        raise CliError(
            "STATE_TRANSITION_ERROR",
            "真实 DSL 演示闭环只允许审批 WAITING_REVIEW 任务",
            [{"field": "status", "reason": f"expected WAITING_REVIEW, got {task.status.value}"}],
        )
    from_status = task.status
    try:
        task.transition_to(TaskStatus.APPROVED, reviewer=reviewer)
    except ValueError as exc:
        raise CliError("STATE_TRANSITION_ERROR", "AI Task 状态非法流转", [{"field": "status", "reason": str(exc)}]) from exc
    store.save(task)
    audit_event = create_review_audit_event(
        task=task,
        action=ReviewAction.APPROVE,
        actor=reviewer,
        from_status=from_status,
        to_status=task.status,
        trace_id=trace_id,
    )
    store.save_review_audit_event(audit_event)
    operation_event = _save_operation_audit(
        store,
        action=OperationAction.REVIEW_APPROVE,
        resource_type=OperationResourceType.AI_TASK,
        resource_id=task.id,
        actor=reviewer,
        trace_id=trace_id,
        before_state=from_status.value,
        after_state=task.status.value,
        detail={"reviewAuditEventId": audit_event.id, "reason": None},
    )
    return {
        "task": task.to_dict(),
        "alreadyApproved": False,
        "auditEvent": audit_event.to_dict(),
        "operationAuditEvent": operation_event,
    }


def _ensure_phase2_real_dsl_review_tasks_from_report(
    store: JsonTaskStore,
    *,
    report: dict[str, Any],
    workflow_report_path: Path,
    input_path: Path,
    trace_id: str,
) -> tuple[dict[str, dict[str, Any]], list[dict[str, Any]], bool]:
    existing_task_ids = {
        kind: str(item.get("taskId"))
        for kind, item in report.get("generatedDsl", {}).items()
        if isinstance(item, dict) and item.get("taskId") and store.get(str(item.get("taskId"))) is not None
    }
    if set(existing_task_ids) == {"lab", "exam", "grading", "ppt"}:
        tasks = {kind: store.get(task_id).to_dict() for kind, task_id in existing_task_ids.items()}
        return tasks, [], False

    tasks = _create_phase2_review_tasks(store, report=report, input_ref=str(input_path), trace_id=trace_id)
    _attach_phase2_task_ids(report, tasks)
    artifacts = _save_phase2_artifacts(
        store,
        report=report,
        input_path=input_path,
        output_path=workflow_report_path,
        tasks=tasks,
        trace_id=trace_id,
    )
    _write_json(workflow_report_path, report)
    return tasks, artifacts, True


def _build_real_dsl_demo_local_verification(
    *,
    workflow_report_path: Path,
    lab_path: Path,
    exam_path: Path,
    grading_path: Path,
    ppt_path: Path,
    output_path: Path,
    trace_id: str,
) -> dict[str, Any]:
    for field, path in (
        ("workflowReport", workflow_report_path),
        ("lab", lab_path),
        ("exam", exam_path),
        ("grading", grading_path),
        ("ppt", ppt_path),
    ):
        _ensure_file(path, field)

    workflow_report = _read_json(workflow_report_path)
    _validate_phase2_report(workflow_report)
    lab = _validate_yaml("lab", lab_path)
    exam = _validate_yaml("exam", exam_path)
    grading = _validate_yaml("grading", grading_path)
    ppt = _validate_yaml("ppt", ppt_path)

    dsl_documents = {"lab": lab, "exam": exam, "grading": grading, "ppt": ppt}
    dsl_paths = {"lab": lab_path, "exam": exam_path, "grading": grading_path, "ppt": ppt_path}
    generated_from_report = workflow_report.get("generatedDsl", {})
    content_quality_summary = workflow_report.get("contentQualitySummary", {})
    content_quality_items = (
        content_quality_summary.get("items", {})
        if isinstance(content_quality_summary, dict) and isinstance(content_quality_summary.get("items"), dict)
        else {}
    )
    items: dict[str, dict[str, Any]] = {}
    blockers: list[dict[str, str]] = []
    warnings: list[dict[str, str]] = []
    ready_for_import_preview_kinds: list[str] = []
    waiting_review_kinds: list[str] = []

    for kind in ("lab", "exam", "grading", "ppt"):
        document = dsl_documents[kind]
        summary = _dsl_summary(kind, dsl_paths[kind], document, "real_llm_demo_local_verification")
        report_item = generated_from_report.get(kind, {}) if isinstance(generated_from_report.get(kind), dict) else {}
        quality_summary = report_item.get("qualitySummary") if isinstance(report_item.get("qualitySummary"), dict) else {}
        content_quality = content_quality_items.get(kind) if isinstance(content_quality_items.get(kind), dict) else {}
        path_matches_report = _path(str(report_item.get("dslPath"))) == dsl_paths[kind] if report_item.get("dslPath") else False
        item = {
            **summary,
            "workflowReportDslPath": report_item.get("dslPath"),
            "pathMatchesWorkflowReport": path_matches_report,
            "providerQualitySummary": quality_summary,
            "contentQualitySummary": content_quality,
            "readyForImportPreview": bool(content_quality.get("readyForImportPreview", kind in {"lab", "exam", "grading"})),
            "requiresRevisionBeforeImportPreview": bool(content_quality.get("requiresRevisionBeforeImportPreview", False)),
            "requiresEvidenceBeforeFinalApproval": bool(content_quality.get("requiresEvidenceBeforeFinalApproval", kind == "grading")),
        }
        items[kind] = item
        if document.get("status") == TaskStatus.WAITING_REVIEW.value:
            waiting_review_kinds.append(kind)
        else:
            blockers.append({"kind": kind, "code": "STATUS_NOT_WAITING_REVIEW", "message": f"{kind} status must be WAITING_REVIEW"})
        if report_item.get("schemaValidated") is not True:
            warnings.append({"kind": kind, "code": "WORKFLOW_REPORT_SCHEMA_FLAG_MISSING", "message": f"{kind} report schemaValidated is not true"})
        if not path_matches_report:
            warnings.append({"kind": kind, "code": "DSL_PATH_DIFFERS_FROM_WORKFLOW_REPORT", "message": f"{kind} input path differs from workflow report"})
        if item["requiresRevisionBeforeImportPreview"]:
            blockers.append({"kind": kind, "code": "CONTENT_REVISION_REQUIRED", "message": f"{kind} content quality requires revision before import preview"})
        elif item["readyForImportPreview"] and kind in {"lab", "exam", "grading"}:
            ready_for_import_preview_kinds.append(kind)

    grading_item = items["grading"]
    if grading_item.get("checkCount", 0) < 1:
        blockers.append({"kind": "grading", "code": "NO_GRADING_CHECKS", "message": "grading DSL must include at least one check"})
    if grading_item.get("assessmentPlanCount", 0) < grading_item.get("checkCount", 0):
        blockers.append({"kind": "grading", "code": "ASSESSMENT_PLAN_INCOMPLETE", "message": "grading assessmentPlan should align with checks"})
    exam_item = items["exam"]
    if exam_item.get("questionCount", 0) < 1:
        blockers.append({"kind": "exam", "code": "NO_EXAM_QUESTIONS", "message": "exam DSL must include at least one question"})
    lab_item = items["lab"]
    if lab_item.get("stepCount", 0) < 1:
        blockers.append({"kind": "lab", "code": "NO_LAB_STEPS", "message": "lab DSL must include at least one step"})
    ppt_item = items["ppt"]
    if ppt_item.get("slideCount", 0) < 1:
        blockers.append({"kind": "ppt", "code": "NO_PPT_SLIDES", "message": "ppt DSL must include at least one slide"})

    ready_for_review = not blockers
    verification = {
        "id": f"real_llm_demo_local_verification_{uuid4().hex[:12]}",
        "phase": "Phase 2",
        "mode": "REAL_LLM_DEMO_LOCAL_VERIFICATION",
        "workflowId": workflow_report.get("workflowId"),
        "sourceWorkflowReportPath": str(workflow_report_path),
        "outputPath": str(output_path),
        "schemaValidated": True,
        "readyForHumanReview": ready_for_review,
        "readyForImportPreviewKinds": ready_for_import_preview_kinds,
        "waitingReviewKinds": waiting_review_kinds,
        "blockerTotal": len(blockers),
        "warningTotal": len(warnings),
        "blockers": blockers,
        "warnings": warnings,
        "items": items,
        "contentQualitySummary": content_quality_summary,
        "nextRecommendedAction": (
            "open_review_detail_and_continue_import_preview" if ready_for_review else "fix_or_regenerate_blocked_dsl"
        ),
        "recommendedCommands": [
            "python lab_cli.py review batch-summary",
            "python lab_cli.py review detail --task-id <task_id>",
            "python lab_cli.py phase2 real-dsl-demo close-loop --workflow-report examples/output/phase2-real-llm-report.json --input examples/input/demo-source.md --confirm-lab-review-approved --confirm-exam-review-approved --confirm-grading-review-approved",
        ],
        "safety": {
            "readOnly": True,
            "newLlmRequestSent": False,
            "realLlmCalled": False,
            "secretsRead": False,
            "networkAccess": False,
            "taskCreated": False,
            "reviewBypassed": False,
            "autoApproveAllowed": False,
            "autoPublishAllowed": False,
            "realPublish": False,
            "databaseWritten": False,
            "sandboxExecuted": False,
            "contestantCodeExecuted": False,
        },
        "traceId": trace_id,
    }
    _write_json(output_path, verification)
    return verification


def _build_real_dsl_demo_close_loop(
    store: JsonTaskStore,
    *,
    workflow_report_path: Path,
    input_path: Path,
    reviewer: str,
    lab_import_output_path: Path,
    exam_import_output_path: Path,
    grading_import_output_path: Path,
    create_mock_imports: bool,
    lab_mock_import_output_path: Path,
    exam_mock_import_output_path: Path,
    grading_mock_import_output_path: Path,
    controlled_submission_path: Path | None,
    controlled_plan_output_path: Path,
    controlled_report_output_path: Path,
    controlled_image: str,
    controlled_stdout_command: str,
    controlled_stdout_expected: list[str],
    controlled_pytest_path: str,
    output_path: Path,
    confirm_lab_review_approved: bool,
    confirm_exam_review_approved: bool,
    confirm_grading_review_approved: bool,
    trace_id: str,
) -> dict[str, Any]:
    _ensure_file(workflow_report_path, "workflowReport")
    _ensure_file(input_path, "input")
    report = _read_json(workflow_report_path)
    _validate_phase2_report(report)
    if report.get("safety", {}).get("realLlmCalled") is not True:
        raise CliError(
            "VALIDATION_ERROR",
            "真实 DSL 演示闭环要求输入为真实 LLM Workflow Report",
            [{"field": "workflowReport.safety.realLlmCalled", "reason": "expected true"}],
        )
    generated = report.get("generatedDsl", {})
    if not all(
        isinstance(generated.get(kind), dict) and generated[kind].get("schemaValidated") is True
        for kind in ("lab", "exam", "grading", "ppt")
    ):
        raise CliError(
            "VALIDATION_ERROR",
            "真实 DSL 演示闭环要求四类 DSL 都已通过 Schema 校验",
            [{"field": "generatedDsl", "reason": "lab/exam/grading/ppt schemaValidated must be true"}],
        )
    missing_confirmations = [
        field
        for field, confirmed in {
            "confirmLabReviewApproved": confirm_lab_review_approved,
            "confirmExamReviewApproved": confirm_exam_review_approved,
            "confirmGradingReviewApproved": confirm_grading_review_approved,
        }.items()
        if not confirmed
    ]
    if missing_confirmations:
        raise CliError(
            "VALIDATION_ERROR",
            "真实 DSL 演示闭环需要显式确认三类可导入 DSL 已人工审核通过",
            [{"field": field, "reason": "必须显式确认"} for field in missing_confirmations],
        )

    tasks, created_artifacts, tasks_created = _ensure_phase2_real_dsl_review_tasks_from_report(
        store,
        report=report,
        workflow_report_path=workflow_report_path,
        input_path=input_path,
        trace_id=trace_id,
    )
    approvals = {
        kind: _approve_task_for_real_dsl_demo_close_loop(
            store,
            task_id=tasks[kind]["id"],
            reviewer=reviewer,
            trace_id=trace_id,
        )
        for kind in ("lab", "exam", "grading")
    }
    import_previews = {
        "lab": create_lab_template_import_preview(
            store,
            task_id=tasks["lab"]["id"],
            reviewer=reviewer,
            output_path=lab_import_output_path,
            trace_id=trace_id,
        ),
        "exam": create_exam_question_import_preview(
            store,
            task_id=tasks["exam"]["id"],
            reviewer=reviewer,
            output_path=exam_import_output_path,
            trace_id=trace_id,
        ),
        "grading": create_grading_rule_import_preview(
            store,
            task_id=tasks["grading"]["id"],
            reviewer=reviewer,
            output_path=grading_import_output_path,
            trace_id=trace_id,
        ),
    }
    mock_imports: dict[str, Any] = {
        "enabled": False,
        "reason": "createMockImports not requested",
        "items": {},
        "mockImportCreatedTotal": 0,
        "databaseWritten": False,
        "realAgentImport": False,
        "realPublish": False,
    }
    if create_mock_imports:
        mock_import_items = {
            "lab": create_lab_template_mock_import(
                store,
                task_id=tasks["lab"]["id"],
                reviewer=reviewer,
                output_path=lab_mock_import_output_path,
                trace_id=trace_id,
            ),
            "exam": create_exam_question_mock_import(
                store,
                task_id=tasks["exam"]["id"],
                reviewer=reviewer,
                output_path=exam_mock_import_output_path,
                trace_id=trace_id,
            ),
            "grading": create_grading_rule_mock_import(
                store,
                task_id=tasks["grading"]["id"],
                reviewer=reviewer,
                output_path=grading_mock_import_output_path,
                trace_id=trace_id,
            ),
        }
        mock_imports = {
            "enabled": True,
            "mode": "LOCAL_PLATFORM_ENTITY_MOCK_IMPORT",
            "items": mock_import_items,
            "outputs": {
                "lab": str(lab_mock_import_output_path),
                "exam": str(exam_mock_import_output_path),
                "grading": str(grading_mock_import_output_path),
            },
            "entityIds": {
                kind: item["agentEntityRecord"]["id"]
                for kind, item in mock_import_items.items()
            },
            "mockImportCreatedTotal": len(mock_import_items),
            "databaseWritten": False,
            "realAgentImport": False,
            "realPublish": False,
            "manualReviewRequired": True,
            "autoPublishAllowed": False,
        }
    controlled_evidence: dict[str, Any] = {
        "enabled": False,
        "reason": "controlledSubmission not provided",
        "planCreated": False,
        "reportCreated": False,
        "sandboxExecuted": False,
        "contestantCodeExecuted": False,
        "commandExecuted": False,
        "pytestExecuted": False,
        "networkEnabled": False,
        "realPublish": False,
    }
    if controlled_submission_path is not None:
        if not controlled_submission_path.exists() or not controlled_submission_path.is_dir():
            raise CliError(
                "VALIDATION_ERROR",
                "受控 Docker evidence 提交目录不存在",
                [{"field": "controlledSubmission", "reason": str(controlled_submission_path)}],
            )
        grading_path_value = generated.get("grading", {}).get("dslPath")
        if not grading_path_value:
            raise CliError(
                "VALIDATION_ERROR",
                "真实 DSL 演示闭环缺少 Grading DSL 路径",
                [{"field": "generatedDsl.grading.dslPath", "reason": "missing"}],
            )
        grading_path = _path(str(grading_path_value))
        _ensure_file(grading_path, "grading")
        controlled_plan = _build_controlled_grading_plan(
            _load_grading_for_controlled_plan(grading_path),
            stdout_command=controlled_stdout_command,
            stdout_expected=controlled_stdout_expected,
            pytest_path=controlled_pytest_path,
            output_path=controlled_plan_output_path,
            trace_id=trace_id,
        )
        _write_json(controlled_plan_output_path, controlled_plan["dsl"])
        controlled_plan_audit = _save_operation_audit(
            store,
            action=OperationAction.CONTROLLED_GRADING_PLAN_BUILD,
            resource_type=OperationResourceType.GRADING_REPORT,
            resource_id=controlled_plan["dsl"]["metadata"]["id"],
            actor=reviewer,
            trace_id=trace_id,
            after_state=TaskStatus.WAITING_REVIEW.value,
            detail={
                "reportType": "CONTROLLED_DOCKER_GRADING_PLAN",
                "mode": controlled_plan["mode"],
                "sourceGradingId": controlled_plan["sourceGradingId"],
                "outputPath": str(controlled_plan_output_path),
                "summary": controlled_plan["summary"],
                "patches": controlled_plan["patches"],
                "deferredChecks": controlled_plan.get("deferredChecks", []),
                "sandboxExecuted": False,
                "contestantCodeExecuted": False,
                "commandExecuted": False,
                "realPublish": False,
            },
        )
        controlled_plan["operationAuditEvent"] = controlled_plan_audit
        controlled_plan["artifact"] = _save_artifact(
            store,
            kind=ArtifactKind.GRADING_DSL,
            path=str(controlled_plan_output_path),
            title="Real LLM Demo Controlled Docker Grading Plan",
            status=ArtifactStatus.WAITING_REVIEW,
            trace_id=trace_id,
            task_id=tasks["grading"]["id"],
            source_ref=str(grading_path),
            metadata={
                "reportType": "CONTROLLED_DOCKER_GRADING_PLAN",
                "sourceGradingId": controlled_plan["sourceGradingId"],
                "summary": controlled_plan["summary"],
                "patches": controlled_plan["patches"],
                "deferredChecks": controlled_plan.get("deferredChecks", []),
                "reviewRequired": True,
                "sandboxRequiredBeforeExecution": True,
            },
        )
        controlled_report = _build_controlled_command_sandbox_report(
            controlled_plan["dsl"],
            controlled_submission_path,
            trace_id,
            image=controlled_image,
        )
        controlled_report["reportPath"] = str(controlled_report_output_path)
        controlled_report_audit = _save_operation_audit(
            store,
            action=OperationAction.CONTROLLED_SANDBOX_RUN,
            resource_type=OperationResourceType.GRADING_REPORT,
            resource_id=controlled_report["id"],
            actor=reviewer,
            trace_id=trace_id,
            after_state="COMPLETED",
            detail={
                "reportType": "CONTROLLED_DOCKER_SANDBOX_RUN",
                "mode": controlled_report["mode"],
                "gradingId": controlled_report["gradingId"],
                "submissionRoot": controlled_report["submissionRoot"],
                "runner": controlled_report["runner"],
                "executionSummary": controlled_report["executionSummary"],
                "score": controlled_report["score"],
                "safety": controlled_report["safety"],
                "isolation": controlled_report.get("isolation", {}),
                "isolationQuality": controlled_report.get("isolationQuality", {}),
                "imageSupplyChain": controlled_report.get("imageSupplyChain", {}),
                "blockedActions": [
                    "executeNotebook",
                    "unknownShellExecution",
                    "networkAccess",
                    "hostExecution",
                    "realPublish",
                ],
            },
        )
        controlled_report["operationAuditEvent"] = controlled_report_audit
        controlled_report["reportDetail"] = build_grading_report_detail(controlled_report, controlled_report_audit)
        controlled_report["artifact"] = _save_artifact(
            store,
            kind=ArtifactKind.GRADING_REPORT,
            path=str(controlled_report_output_path),
            title="Real LLM Demo Controlled Docker Sandbox Report",
            status=ArtifactStatus.COMPLETED,
            trace_id=trace_id,
            task_id=tasks["grading"]["id"],
            source_ref=str(controlled_plan_output_path),
            metadata={
                "reportType": "CONTROLLED_DOCKER_SANDBOX_RUN",
                "gradingId": controlled_report["gradingId"],
                "submissionRoot": controlled_report["submissionRoot"],
                "executionSummary": controlled_report["executionSummary"],
                "score": controlled_report["score"],
                "checkSummary": controlled_report.get("checkSummary", {}),
                "assessmentPlanSummary": controlled_report.get("assessmentPlanSummary", {}),
                "isolation": controlled_report.get("isolation", {}),
                "isolationQuality": controlled_report.get("isolationQuality", {}),
                "imageSupplyChain": controlled_report.get("imageSupplyChain", {}),
                "safety": controlled_report["safety"],
            },
        )
        _write_json(controlled_report_output_path, controlled_report)
        controlled_evidence = {
            "enabled": True,
            "mode": "CONTROLLED_DOCKER_SANDBOX_POC",
            "sourceGradingPath": str(grading_path),
            "planPath": str(controlled_plan_output_path),
            "reportPath": str(controlled_report_output_path),
            "submissionPath": str(controlled_submission_path),
            "image": controlled_image,
            "plan": {
                "mode": controlled_plan["mode"],
                "summary": controlled_plan["summary"],
                "patches": controlled_plan["patches"],
                "deferredChecks": controlled_plan.get("deferredChecks", []),
                "artifact": controlled_plan["artifact"],
                "operationAuditEvent": controlled_plan_audit,
            },
            "report": {
                "id": controlled_report["id"],
                "mode": controlled_report["mode"],
                "gradingId": controlled_report["gradingId"],
                "executionSummary": controlled_report["executionSummary"],
                "score": controlled_report["score"],
                "checkSummary": controlled_report.get("checkSummary", {}),
                "runner": controlled_report["runner"],
                "safety": controlled_report["safety"],
                "artifact": controlled_report["artifact"],
                "operationAuditEvent": controlled_report_audit,
            },
            "planCreated": True,
            "reportCreated": True,
            "sandboxExecuted": bool(controlled_report["safety"].get("sandboxExecuted", False)),
            "contestantCodeExecuted": bool(controlled_report["safety"].get("contestantCodeExecuted", False)),
            "commandExecuted": bool(controlled_report["safety"].get("commandExecuted", False)),
            "pytestExecuted": bool(controlled_report["safety"].get("pytestExecuted", False)),
            "networkEnabled": bool(controlled_report["safety"].get("networkEnabled", False)),
            "realPublish": False,
            "manualReviewRequired": True,
            "autoApproveAllowed": False,
        }
    review_details = {kind: build_review_detail(store, tasks[kind]["id"]) for kind in ("lab", "exam", "grading", "ppt")}
    signoff = {
        kind: review_details[kind]["platformImportPreviewSignoff"]
        for kind in ("lab", "exam", "grading")
        if review_details.get(kind)
    }
    platform_import_preview_totals = {
        kind: review_details[kind]["platformImportPreview"]["total"]
        for kind in ("lab", "exam", "grading")
        if review_details.get(kind)
    }
    importable_agent_entity_scope = {"lab_template", "exam_question", "grading_rule"}
    agent_entity_readiness_report = build_agent_entity_readiness_report(
        store,
        agent_entities=importable_agent_entity_scope,
    )
    ready_for_demo = (
        len(signoff) == 3
        and all(item.get("readyForHumanSignoff") is True for item in signoff.values())
        and review_details.get("ppt", {}).get("task", {}).get("status") == TaskStatus.WAITING_REVIEW.value
    )
    close_loop = {
        "component": "RealLlmDemoCloseLoop",
        "mode": "REAL_LLM_DEMO_CLOSE_LOOP",
        "workflowReportPath": str(workflow_report_path),
        "inputPath": str(input_path),
        "reviewer": reviewer,
        "tasksCreated": tasks_created,
        "createdTasks": tasks,
        "createdArtifacts": created_artifacts,
        "approvals": approvals,
        "importPreviews": import_previews,
        "mockImports": mock_imports,
        "agentEntityReadinessReport": agent_entity_readiness_report,
        "agentEntityReadinessScope": {
            "agentEntities": sorted(importable_agent_entity_scope),
            "reason": "real demo close-loop imports Lab, Exam and Grading; PPT stays WAITING_REVIEW for page review",
            "pptDeckIncluded": False,
        },
        "reviewDetails": review_details,
        "platformImportPreviewSignoff": signoff,
        "controlledGradingEvidence": controlled_evidence,
        "outputPath": str(output_path),
        "summary": {
            "realLlmCalled": True,
            "dslValidatedTotal": 4,
            "approvedImportableTaskTotal": len(approvals),
            "importPreviewTotal": sum(platform_import_preview_totals.values()),
            "signoffReadyTotal": sum(1 for item in signoff.values() if item.get("readyForHumanSignoff") is True),
            "mockImportCreatedTotal": mock_imports["mockImportCreatedTotal"],
            "agentEntityReadyTotal": agent_entity_readiness_report["summary"]["readyForManualAgentReviewTotal"],
            "agentEntityRequiredTotal": agent_entity_readiness_report["summary"]["requiredTotal"],
            "agentEntityMissingPreviewTotal": agent_entity_readiness_report["summary"]["missingPreviewTotal"],
            "agentEntityMissingMockImportTotal": agent_entity_readiness_report["summary"]["missingMockImportTotal"],
            "allPlatformEntitiesReadyForManualReview": agent_entity_readiness_report["summary"][
                "allReadyForManualPlatformReview"
            ],
            "controlledGradingEvidenceEnabled": controlled_evidence["enabled"],
            "controlledGradingPlanCreated": controlled_evidence["planCreated"],
            "controlledGradingReportCreated": controlled_evidence["reportCreated"],
            "controlledGradingEvidenceExecutedTotal": (
                controlled_evidence.get("report", {}).get("executionSummary", {}).get("executed", 0)
                if controlled_evidence["enabled"]
                else 0
            ),
            "controlledGradingEvidenceEarnedScore": (
                controlled_evidence.get("report", {}).get("score", {}).get("earnedScore")
                if controlled_evidence["enabled"]
                else None
            ),
            "controlledGradingEvidenceTotalScore": (
                controlled_evidence.get("report", {}).get("score", {}).get("totalScore")
                if controlled_evidence["enabled"]
                else None
            ),
            "pptWaitingReview": review_details.get("ppt", {}).get("task", {}).get("status")
            == TaskStatus.WAITING_REVIEW.value,
            "readyForDemo": ready_for_demo,
        },
        "safety": {
            "newLlmRequestSent": False,
            "secretsRead": False,
            "networkAccess": False,
            "databaseWritten": False,
            "realAgentImport": False,
            "mockStoreWritten": bool(mock_imports["enabled"]),
            "autoPublishAllowed": False,
            "realPublishAllowed": False,
            "realPublish": False,
            "sandboxExecuted": controlled_evidence["sandboxExecuted"],
            "contestantCodeExecuted": controlled_evidence["contestantCodeExecuted"],
            "commandExecuted": controlled_evidence["commandExecuted"],
            "pytestExecuted": controlled_evidence["pytestExecuted"],
            "networkEnabledForControlledGrading": controlled_evidence["networkEnabled"],
            "pptAutoApproved": False,
        },
    }
    _write_json(output_path, close_loop)
    return close_loop


