def _create_phase2_exam_tasks(
    store: JsonTaskStore,
    *,
    report: dict[str, Any],
    trace_id: str,
) -> dict[str, dict[str, Any]]:
    generated = report["generatedDsl"]
    lab_id = str(report["labDslInput"]["labId"])
    task_specs = {
        "exam": (
            "EXAM_GENERATION",
            "Phase 2 Mock Exam conversion",
            "lab_dsl",
            lab_id,
            generated["exam"]["dslPath"],
        ),
        "grading": (
            "GRADING_GENERATION",
            "Phase 2 Mock Grading conversion",
            "exam_dsl",
            generated["exam"]["dslId"],
            generated["grading"]["dslPath"],
        ),
    }
    tasks: dict[str, dict[str, Any]] = {}
    for kind, (task_type, title, input_type, source_ref, final_result_path) in task_specs.items():
        task = create_waiting_review_task(
            task_type=task_type,
            title=title,
            input_type=input_type,
            input_ref=source_ref,
            final_result_path=final_result_path,
            trace_id=trace_id,
        )
        store.save(task)
        tasks[kind] = task.to_dict()
    return tasks


def _attach_phase2_exam_task_ids(report: dict[str, Any], tasks: dict[str, dict[str, Any]]) -> None:
    for step in report["steps"]:
        kind = step.get("kind")
        if kind in tasks:
            step["taskId"] = tasks[kind]["id"]
            report["generatedDsl"][kind]["taskId"] = tasks[kind]["id"]


