def _validate_phase2_exam_report(report: dict[str, Any]) -> None:
    if report.get("phase") != "Phase 2":
        raise CliError("VALIDATION_ERROR", "Phase 2 Exam Workflow 报告格式错误", [{"field": "phase", "reason": "必须是 Phase 2"}])
    if report.get("mode") != "MOCK_ONLY":
        raise CliError("VALIDATION_ERROR", "Phase 2 Exam Workflow 报告格式错误", [{"field": "mode", "reason": "必须是 MOCK_ONLY"}])
    if report.get("workflowId") != PHASE2_EXAM_WORKFLOW_ID:
        raise CliError("VALIDATION_ERROR", "Phase 2 Exam Workflow 报告格式错误", [{"field": "workflowId", "reason": "不支持的 Workflow"}])
    generated = report.get("generatedDsl")
    if not isinstance(generated, dict) or set(generated) != {"exam", "grading"}:
        raise CliError("VALIDATION_ERROR", "Phase 2 Exam Workflow 报告格式错误", [{"field": "generatedDsl", "reason": "缺少 Exam / Grading 摘要"}])
    if report.get("candidateSafeExamPreview", {}).get("answersRemoved") is not True:
        raise CliError("VALIDATION_ERROR", "Phase 2 Exam Workflow 报告格式错误", [{"field": "candidateSafeExamPreview", "reason": "候选人预览必须移除答案"}])
    quality_signals = report.get("qualitySignals")
    if not isinstance(quality_signals, dict) or quality_signals.get("overall", {}).get("reviewRequired") is not True:
        raise CliError("VALIDATION_ERROR", "Phase 2 Exam Workflow 报告格式错误", [{"field": "qualitySignals", "reason": "缺少审核质量信号"}])
    for kind, item in generated.items():
        if item.get("status") != TaskStatus.WAITING_REVIEW.value:
            raise CliError("VALIDATION_ERROR", "Phase 2 Exam Workflow 报告格式错误", [{"field": f"generatedDsl.{kind}.status", "reason": "必须等待人工审核"}])
    if any(report.get("safety", {}).get(field) is not False for field in ("realLlmCalled", "realAgentStarted", "realCloudResourceCreated", "sandboxExecuted", "contestantCodeExecuted", "realPublish")):
        raise CliError("VALIDATION_ERROR", "Phase 2 Exam Workflow 报告格式错误", [{"field": "safety", "reason": "包含被禁用的真实执行标记"}])


