def _validate_phase2_ppt_report(report: dict[str, Any]) -> None:
    if report.get("phase") != "Phase 2":
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "phase", "reason": "必须是 Phase 2"}])
    if report.get("mode") != "MOCK_ONLY":
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "mode", "reason": "必须是 MOCK_ONLY"}])
    if report.get("workflowId") != PHASE2_PPT_WORKFLOW_ID:
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "workflowId", "reason": "不支持的 Workflow"}])
    generated = report.get("generatedDsl")
    if not isinstance(generated, dict) or set(generated) != {"ppt"}:
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "generatedDsl", "reason": "缺少 PPT 摘要"}])
    if generated["ppt"].get("status") != TaskStatus.WAITING_REVIEW.value:
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "generatedDsl.ppt.status", "reason": "必须等待人工审核"}])
    slide_plan = report.get("slidePlan")
    if not isinstance(slide_plan, dict) or not slide_plan.get("slides"):
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "slidePlan", "reason": "必须先生成 slide plan"}])
    if slide_plan.get("artifactGenerated") is not False or slide_plan.get("pptFileGenerated") is not False:
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "slidePlan", "reason": "Phase 2 Mock 不生成真实 PPT 文件"}])
    review_summary = report.get("reviewSummary", {})
    if review_summary.get("artifactGenerated") is not False or review_summary.get("pptFileGenerated") is not False:
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "reviewSummary", "reason": "Phase 2 Mock 不生成真实 PPT 文件"}])
    if any(report.get("safety", {}).get(field) is not False for field in ("realLlmCalled", "realAgentStarted", "realCloudResourceCreated", "sandboxExecuted", "contestantCodeExecuted", "realPublish")):
        raise CliError("VALIDATION_ERROR", "Phase 2 PPT Workflow 报告格式错误", [{"field": "safety", "reason": "包含被禁用的真实执行标记"}])


def _material_summary(analysis: dict[str, Any]) -> dict[str, Any]:
    return {
        "title": analysis["title"],
        "fileType": analysis["fileType"],
        "riskCount": analysis["riskCount"],
        "unknownShellExecuted": analysis["unknownShellExecuted"],
        "requiresHumanReview": analysis["requiresHumanReview"],
    }


def _workflow_steps_from_report(report: dict[str, Any]) -> list:
    workflow_steps = []
    for index, step in enumerate(report.get("steps", []), start=1):
        detail = {
            key: value
            for key, value in step.items()
            if key not in {"name", "status"}
        }
        workflow_steps.append(create_workflow_step(step["name"], index, detail))
    return workflow_steps


